local config = {
  ui_story_5076_50760100_1_dialog_content = "Hurry... Wake up, Re...!",
  ui_story_5076_50760100_2_dialog_content = "Who's there?",
  ui_story_5076_50760100_3_dialog_content = "He's trapped in the nightmare... we must... the Colossus...",
  ui_story_5076_50760100_4_dialog_content = "Wait, aren't you...?",
  ui_story_5076_50760100_5_dialog_content = "<size=45>Come back—</size>",
  ui_story_5076_50760100_6_dialog_content = "Oh, you're finally awake. You scared me there for a minute.",
  ui_story_5076_50760100_7_dialog_content = "What's with that look? Don't you remember your Caelestite friend? It's me, Ludweiss!",
  ui_story_5076_50760100_8_dialog_content = "It looked like you were having a really bad nightmare just now. You weren't waking up, so Marcela called me over.",
  ui_story_5076_50760100_9_dialog_content = "Marcela? Marcela...",
  ui_story_5076_50760100_10_dialog_content = "Commander? Are you alright? It's one thing to forget about a wanderer like me, but how could you forget about your fiancée?",
  ui_story_5076_50760100_11_dialog_content = "I'm right here, Adras... Are you feeling unwell? You look so pallid.",
  ui_story_5076_50760100_12_dialog_content = "Marcela... Your clothes...",
  ui_story_5076_50760100_13_dialog_content = "... D-Don't stare at me like that. Ludweiss is still here, you know.",
  ui_story_5076_50760100_14_dialog_content = "Still enjoying the view even after the last few days, eh, Commander? Makes sense, since Marcela's outfit is so much cuter than before.",
  ui_story_5076_50760100_15_dialog_content = "Please don't tease me like that...",
  ui_story_5076_50760100_16_dialog_content = "And my clothes...",
  ui_story_5076_50760100_17_dialog_content = "Are you sure you're awake? Don't tell me you forgot about the wedding.",
  ui_story_5076_50760100_18_dialog_content = "The wedding... That's right, I was dreaming just now.",
  ui_story_5076_50760100_19_dialog_content = "I was standing in darkness, and all I could see was a mural on a wall... It was vague, but I think it was about a wedding.",
  ui_story_5076_50760100_20_dialog_content = "I was trapped there for so long, and I couldn't remember anything. It was a terrible dream... One that lasted a thousand years.",
  ui_story_5076_50760100_21_dialog_content = "I don't think Adras was just having a nightmare, Ludweiss. Do you think he might be sick?",
  ui_story_5076_50760100_22_dialog_content = "I can't say for sure, but let me try using my psychic powers on him.",
  ui_story_5076_50760100_23_dialog_content = "Adras, are you awake?",
  ui_story_5076_50760100_24_dialog_content = "...",
  ui_story_5076_50760100_25_dialog_content = "This is—!",
  ui_story_5076_50760100_26_dialog_content = "Why... Why are you crying?",
  ui_story_5076_50760100_27_dialog_content = "Were you dreaming about the distant future, Adras? Or did you dream of me after all those years?",
  ui_story_5076_50760100_28_dialog_content = "What are you talking about, Ludweiss?",
  ui_story_5076_50760100_29_dialog_content = "Ah?",
  ui_story_5076_50760100_30_dialog_content = "Sorry, I fell into Adras' nightmare and lost myself for a second there...",
  ui_story_5076_50760100_31_dialog_content = "So even Caelestites can be bothered by dreams, eh?",
  ui_story_5076_50760100_32_dialog_content = "Y-You're finally awake... Hey, stop laughing! Just be thankful I dragged you out of that nightmare!",
  ui_story_5076_50760100_33_dialog_content = "Thank you, Ludweiss. I was beginning to worry myself sick.",
  ui_story_5076_50760100_34_dialog_content = "Thank you... But what you said about my dream just now—",
  ui_story_5076_50760100_35_dialog_content = "Commander, I apologize for the intrusion, but there's an urgent message!",
  ui_story_5076_50760100_36_dialog_content = "General Achilles orders the legion to assemble.",
  ui_story_5076_50760100_37_dialog_content = "Understood. I'll be there shortly.",
  ui_story_5076_50760100_38_dialog_content = "Forgive me for making the two of you worry so much. I promise I'll be back soon.",
  ui_story_5076_50760100_39_dialog_content = "Heh, just try not to keep Marcela waiting.",
  ui_story_5076_50760100_40_dialog_content = "Then again, you kept talking about a wedding in your sleep, so you probably don't need me to remind you.",
  ui_story_5076_50760100_41_dialog_content = "D-Don't listen to her. The mission comes first, and General Achilles is waiting for you.",
  ui_story_5076_50760100_42_dialog_content = "I'll be back as soon as possible.",
  ui_story_5076_50760100_43_dialog_content = "... The fiendish Eclipsites have reappeared to the north, threatening to invade our borders.",
  ui_story_5076_50760100_44_dialog_content = "The king has ordered us to eradicate those monsters!",
  ui_story_5076_50760100_45_dialog_content = "Once you are dismissed, gather your equipment and say farewell to your loved ones.",
  ui_story_5076_50760100_46_dialog_content = "Understood!",
  ui_story_5076_50760100_47_dialog_content = "How has normal life been treating you, Adras?",
  ui_story_5076_50760100_48_dialog_content = "It's peaceful. I'm still not entirely used to it.",
  ui_story_5076_50760100_49_dialog_content = "Commander, it's time to leave the battles behind and accept this peaceful life.",
  ui_story_5076_50760100_50_dialog_content = "You're getting married soon, but you're still... It's quite concerning.",
  ui_story_5076_50760100_51_dialog_content = "We're about to leave, Adras, but congratulations on your wedding.",
  ui_story_5076_50760100_52_dialog_content = "What are you talking about? It almost sounds like you have no intention of letting me go on this mission.",
  ui_story_5076_50760100_53_dialog_content = "That's right. The Eclipsites reported in the north don't warrant the full extent of our forces.",
  ui_story_5076_50760100_54_dialog_content = "Your mission is to stay here and enjoy the life you've made for yourself.",
  ui_story_5076_50760100_55_dialog_content = "You've sacrificed years of your life for the sake of others, and now it's time for you to pursue your own happiness. At the very least, you can see all that you've protected with Marcela at your side.",
  ui_story_5076_50760100_56_dialog_content = "General, I...",
  ui_story_5076_50760100_57_dialog_content = "Commander Adras, in accordance with the kingdom's laws and policies, you are hereby placed on matrimonial leave so that you may enjoy your wedding!",
  ui_story_5076_50760100_58_dialog_content = "Put your mind at ease and enjoy your time off.",
  ui_story_5076_50760100_59_dialog_content = "Congratulations, Commander Adras!",
  ui_story_5076_50760100_60_dialog_content = "You...",
  ui_story_5076_50760100_61_dialog_content = "Maybe you'll have a little one already when we get back!",
  ui_story_5076_50760100_62_dialog_content = "Commander might not be the best with kids. Fingers crossed his kid is more like their mom.",
  ui_story_5076_50760100_63_dialog_content = "Alright, everyone, leave your gifts and go about your business. Adras, you stay here.",
  ui_story_5076_50760100_64_dialog_content = "Did you hear about <color=#FFB400>High Priest Lucius</color> returning to the royal capital?",
  ui_story_5076_50760100_65_dialog_content = "Lucius? You mean he...",
  ui_story_5076_50760100_66_dialog_content = "Commander Adras, the rebels are all here.",
  ui_story_5076_50760100_67_dialog_content = "Let me go, let me go! Do you know who I am?",
  ui_story_5076_50760100_68_dialog_content = "I'm Lucius, the High Priest you should all revere! Show me some respect!",
  ui_story_5076_50760100_69_dialog_content = "All I see is a traitor, and nothing more.",
  ui_story_5076_50760100_70_dialog_content = "Oh? So our mighty hero is the one who set this up? No wonder they had the audacity to storm in with such a meager force.",
  ui_story_5076_50760100_71_dialog_content = "How dare you be so pretentious when you're nothing but a mere commoner yourself!",
  ui_story_5076_50760100_72_dialog_content = "You endangered the peace of the kingdom, and are hereby under arrest!",
  ui_story_5076_50760100_73_dialog_content = "Repent for the harm you've done to the people.",
  ui_story_5076_50760100_74_dialog_content = "Unhand me! Who do you think you are?! You're nothing more than the prime elder's pawn!",
  ui_story_5076_50760100_75_dialog_content = "You'll live to regret this! Mark my words, I'll personally make you pay—",
  ui_story_5076_50760100_76_dialog_content = "Wasn't he found guilty of treason?",
  ui_story_5076_50760100_77_dialog_content = "Yes, but Lucius is still a noble. Despite having contact with the rebels, he was only found guilty by association.",
  ui_story_5076_50760100_78_dialog_content = "When he fell from power, the Elder Council's influence grew unprecedentedly. His return to political relevance is only so the king can keep the Prime Elder in check.",
  ui_story_5076_50760100_79_dialog_content = "The king and I have been friends for so many years, yet he's become more and more like a stranger to me lately. It seems he's gotten quite skilled at using methods such as these.",
  ui_story_5076_50760100_80_dialog_content = "Be careful, Adras.",
  ui_story_5076_50760100_81_dialog_content = "I'm only carrying out my orders. He shouldn't hold it against me.",
  ui_story_5076_50760100_82_dialog_content = "Not everyone abides by rules and reason as much as you do.",
  ui_story_5076_50760100_83_dialog_content = "In any case, remember to stay vigilant even in your peaceful, new life. Misfortune is always lurking in the shadows.",
  ui_story_5076_50760100_84_dialog_content = "Back when the rebel army was occupying the city... That was when I met her.",
  ui_story_5076_50760100_85_dialog_content = "There's more to this world than just misfortune.",
  ui_story_5076_50760100_86_dialog_content = "You've changed, Adras.",
  ui_story_5076_50760100_87_dialog_content = "I'm happy for you. It seems you've finally found the answers you were looking for in life.",
  ui_story_5076_50760100_88_dialog_content = "Alright, that's all from me, the gifts are all here too. Enjoy the good times ahead!",
  ui_story_5076_50760100_89_dialog_content = "I'll be praying for your safe return, General Achilles.",
  ui_story_5076_50760100_90_dialog_content = "Thanks, now go. It's almost time for the wedding, so don't keep Marcela waiting.",
  ui_story_5076_50760200_1_dialog_content = "Look there! That's the legendary hero, Adras, walking towards us!",
  ui_story_5076_50760200_2_dialog_content = "Adras? The hero who quelled the rebellion back in the day?",
  ui_story_5076_50760200_3_dialog_content = "Back in the day? I'm kinda new here; what happened at that time?",
  ui_story_5076_50760200_4_dialog_content = "Let me tell you, during those years...",
  ui_story_5076_50760200_5_dialog_content = "Rebels! I, on behalf of the Northwind Legion, am here to offer you a chance: your reinforcements have been cut off; SURRENDER NOW!",
  ui_story_5076_50760200_6_dialog_content = "Dream on! As long as this city stands, we won't lose...",
  ui_story_5076_50760200_7_dialog_content = "Archers! Fire! Someone, bring those folks over here! Let them shield the attack!",
  ui_story_5076_50760200_8_dialog_content = "The first legion? So what? With all these hostages we've got in the city...",
  ui_story_5076_50760200_9_dialog_content = "Captain, look! They're charging at us with shields held high!",
  ui_story_5076_50760200_10_dialog_content = "What? They think they're invincible? Keep firing! Don't let them get any closer to the city walls!",
  ui_story_5076_50760200_11_dialog_content = "Urgh—!",
  ui_story_5076_50760200_12_dialog_content = "What's happening down there?",
  ui_story_5076_50760200_13_dialog_content = "A squad sneaked in from the rear during the chaos! They're already in the city!",
  ui_story_5076_50760200_14_dialog_content = "How many are there?",
  ui_story_5076_50760200_15_dialog_content = "Only a handful of them, each wielding just a sword—they climbed the wall with their bare hands!",
  ui_story_5076_50760200_16_dialog_content = "Useless bunch! Do I have to handle this myself?!",
  ui_story_5076_50760200_17_dialog_content = "But... the dude leading them is crazy strong...",
  ui_story_5076_50760200_18_dialog_content = "Stop resisting! I'm not going to attack unarmed civilians!",
  ui_story_5076_50760200_19_dialog_content = "You're citizens of this kingdom as well, so stop hurting your compatriots!",
  ui_story_5076_50760200_20_dialog_content = "Foolish idiots, surrounded by us yet still acting tough... GET THEM!",
  ui_story_5076_50760200_21_dialog_content = "You had your chance, villains—All forces, kill the enemy on sight!",
  ui_story_5076_50760200_22_dialog_content = "Take down their commander and clear a path for our brothers attacking the city! On me!",
  ui_story_5076_50760200_23_dialog_content = "Stop them! Get the archers over here!",
  ui_story_5076_50760200_24_dialog_content = "Captain, bad news! Someone raided the dungeon holding the residents, and our warehouse is on fire!",
  ui_story_5076_50760200_25_dialog_content = "Captain! The western gate's been opened; someone's helping civilians escape!",
  ui_story_5076_50760200_26_dialog_content = "Cap-Captain! Behind us!",
  ui_story_5076_50760200_27_dialog_content = "<size=40>Damn it!</size> What the hell is happening again—!",
  ui_story_5076_50760200_28_dialog_content = "<size=45>Die!</size>",
  ui_story_5076_50760200_29_dialog_content = "Captain!",
  ui_story_5076_50760200_30_dialog_content = "Rebels! Your captain is dead! Lay down your weapons, all of you!",
  ui_story_5076_50760200_31_dialog_content = "There's been enough senseless killing in the city, but now is the time to end this! No one else has to die as long as you bring me your leader!",
  ui_story_5076_50760200_32_dialog_content = "Why should we believe you? What's your proof...",
  ui_story_5076_50760200_33_dialog_content = "Because I am Adras!",
  ui_story_5076_50760200_34_dialog_content = "The man who will end this war!",
  ui_story_5076_50760200_35_dialog_content = "Look how fast he's running! Maybe he's joined the expedition too?",
  ui_story_5076_50760200_36_dialog_content = "If that hero is going there too, my son in the army should be safer, right...?",
  ui_story_5076_50760200_37_dialog_content = "Did you forget? The hero is about to get married; the ceremony is all set.",
  ui_story_5076_50760200_38_dialog_content = "Marcela!",
  ui_story_5076_50760200_39_dialog_content = "Wow! Don't scare me like that! What's the matter?",
  ui_story_5076_50760200_40_dialog_content = "I didn't keep you waiting too long... Did I?",
  ui_story_5076_50760200_41_dialog_content = "I'm fine. It's you that I'm worrying about. What's happening in the Legion?",
  ui_story_5076_50760200_42_dialog_content = "Eclipsites are starting to concentrate in the north. The general has orders to wipe them out.",
  ui_story_5076_50760200_43_dialog_content = "And you're not going?",
  ui_story_5076_50760200_44_dialog_content = "General Achilles says that their numbers don't require my presence. He put me on leave so that we could spend our wedding in peace.",
  ui_story_5076_50760200_45_dialog_content = "If it's for my sake, you don't have to—",
  ui_story_5076_50760200_46_dialog_content = "You said the orphanage's roof needed fixing, didn't you? I have time to take care of it now.",
  ui_story_5076_50760200_47_dialog_content = "I'd like to spend a few days with you outside the city, if that's alright?",
  ui_story_5076_50760200_48_dialog_content = "... Sure. I'd love to.",
  ui_story_5076_50760200_49_dialog_content = "<color=#e8d9bb>Several days later</color>",
  ui_story_5076_50760200_50_dialog_content = "The wedding's just around the corner, and you two suddenly want to take a trip out of the city?",
  ui_story_5076_50760200_51_dialog_content = "Huh? I just thought we'd be busy for the next few days, so I wanted to prepare enough teaching material for the children.",
  ui_story_5076_50760200_52_dialog_content = "And you couldn't just leave that up to me?",
  ui_story_5076_50760200_53_dialog_content = "Aren't you traveling to a new place soon? Besides, you've already helped me enough by compiling it. I can't keep relying on you.",
  ui_story_5076_50760200_54_dialog_content = "Going on the road again, eh? Take good care of yourself, Ludweiss.",
  ui_story_5076_50760200_55_dialog_content = "Same to you two... The orphanage looks a lot nicer this time around. You've really been giving it your all, haven't you, Adras?",
  ui_story_5076_50760200_56_dialog_content = "I don't mind, as long as it's for the children.",
  ui_story_5076_50760200_57_dialog_content = "So what are you up to now?",
  ui_story_5076_50760200_58_dialog_content = "Making bread.",
  ui_story_5076_50760200_59_dialog_content = "What a fancy shape. It doesn't suit you at all, you know.",
  ui_story_5076_50760200_60_dialog_content = "You can have some, if you'd like.",
  ui_story_5076_50760200_61_dialog_content = "Adras is quite skilled at making bread. Before he became a soldier, he all but worshipped the local baker and even served as his apprentice for a time.",
  ui_story_5076_50760200_62_dialog_content = "That's because he would always hand out bread to children on the street.",
  ui_story_5076_50760200_63_dialog_content = "Adras, it's Adras!",
  ui_story_5076_50760200_64_dialog_content = "Don't hug me. I'm covered in flour.",
  ui_story_5076_50760200_65_dialog_content = "We're not hungry yet; let's practice first.",
  ui_story_5076_50760200_66_dialog_content = "Please teach us some sword skills; we wanna protect Marcela too!",
  ui_story_5076_50760200_67_dialog_content = "You won't be able to eat this bread if I don't bake it right now.",
  ui_story_5076_50760200_68_dialog_content = "Sword skills first! That's more important, you know!",
  ui_story_5076_50760200_69_dialog_content = "Marcela...",
  ui_story_5076_50760200_70_dialog_content = "Give him some space. He'll be with you once he finishes putting the bread in the oven, okay?",
  ui_story_5076_50760200_71_dialog_content = "Fine...",
  ui_story_5076_50760200_72_dialog_content = "Adras is helpless around those kids, and yet you can get them to listen with just a few words.",
  ui_story_5076_50760200_73_dialog_content = "Well, I have been keeping them under control ever since they were little, after all.",
  ui_story_5076_50760200_74_dialog_content = "I almost forgot... Even though you're younger than me, you've been managing this orphanage for years now. You really are an incredible person.",
  ui_story_5076_50760200_75_dialog_content = "I've seen all kinds of war and strife in my travels, but it's rare to meet someone like you who helps children who have lost everything.",
  ui_story_5076_50760200_76_dialog_content = "Maybe it's because... I also grew up in an orphanage.",
  ui_story_5076_50760200_77_dialog_content = "And even though I lost everything, I've had so many kind-hearted people watching over me all this time. This is my way to express my appreciation and return the kindness shown to me by the world.",
  ui_story_5076_50760200_78_dialog_content = "... That should do it. Marcela, I'll... go train with the children now.",
  ui_story_5076_50760200_79_dialog_content = "Don't go too hard on them, okay?",
  ui_story_5076_50760200_80_dialog_content = "Ludweiss.",
  ui_story_5076_50760200_81_dialog_content = "Hmm?",
  ui_story_5076_50760200_82_dialog_content = "I'm sure you've seen more tragedies in your travels than you can count... But please don't let it dishearten you. This world is still full of goodness.",
  ui_story_5076_50760200_83_dialog_content = "Please don't stop believing in other people.",
  ui_story_5076_50760200_84_dialog_content = "Of course I know that. After all, meeting the two of you was just another good thing about this world.",
  ui_story_5076_50760200_85_dialog_content = "It's amazing to think that I arrived in this kingdom just as everyone was celebrating Adras' return.",
  ui_story_5076_50760200_86_dialog_content = "Even now, I can still remember the smiles and cheers on every street of the royal capital.",
  ui_story_5076_50760200_87_dialog_content = "I know what you mean! Meeting the hero Adras for the first time always has a dazzling effect on people.",
  ui_story_5076_50760200_88_dialog_content = "Sounds like a lot of bragging to me, soon-to-be Mrs. Adras.",
  ui_story_5076_50760200_89_dialog_content = "Th-That's not what I meant!",
  ui_story_5076_50760200_90_dialog_content = "I have heard of Adras' heroic tale all the time too. That's how I understand why people feel so safe when they see him.",
  ui_story_5076_50760200_91_dialog_content = "The children all look up to him as well. He's everyone's hero, but...",
  ui_story_5076_50760200_92_dialog_content = "Marcela?",
  ui_story_5076_50760200_93_dialog_content = "Huh? O-Oh, it's nothing!",
  ui_story_5076_50760200_94_dialog_content = "I forgot to ask earlier, but where are you going next?",
  ui_story_5076_50760200_95_dialog_content = "I'm going to travel around the kingdom with some new friends before returning here. They're pretty interesting people, just like Adras.",
  ui_story_5076_50760200_96_dialog_content = "Unfortunately, now's not the time to talk about this stuff. I'll be sure to introduce you to them when I have the chance.",
  ui_story_5076_50760200_97_dialog_content = "You're going to stay for our wedding at least, right...?",
  ui_story_5076_50760200_98_dialog_content = "Of course I am. Don't worry about that.",
  ui_story_5076_50760300_1_dialog_content = "Looking for something, Adras? Why do you look so worried?",
  ui_story_5076_50760300_2_dialog_content = "Ludweiss, have you seen Marcela? She disappeared without saying a word this morning...",
  ui_story_5076_50760300_3_dialog_content = "Don't be so concerned. It's just one morning.",
  ui_story_5076_50760300_4_dialog_content = "... With the wedding approaching, it feels like something is weighing on her heart, but she won't tell me what it is.",
  ui_story_5076_50760300_5_dialog_content = "Could you help me look for her, Ludweiss?",
  ui_story_5076_50760300_6_dialog_content = "I see. Don't worry. I'll use my psychic powers to help you find her.",
  ui_story_5076_50760300_7_dialog_content = "Just calm down and follow me.",
  ui_story_5076_50760300_8_dialog_content = "There! She's in front of the temple!",
  ui_story_5076_50760300_9_dialog_content = "Huh? She's... feeding a cat?",
  ui_story_5076_50760300_10_dialog_content = "No, she looks like she's in a daze. That cat's almost done eating the food she brought it—Something must be bothering her after all.",
  ui_story_5076_50760300_11_dialog_content = "Ludweiss... Could you please go talk to her?",
  ui_story_5076_50760300_12_dialog_content = "What's the matter? Is our fearless commander scared that his own fiancée doesn't want to talk to him?",
  ui_story_5076_50760300_13_dialog_content = "No... I'm scared that she won't tell me the truth.",
  ui_story_5076_50760300_14_dialog_content = "But if she talks to a mind-reading Caelestite, she'll most likely tell you what's on her mind... I don't want her to hide her troubles from me for my sake.",
  ui_story_5076_50760300_15_dialog_content = "Fine, fine. Honestly, you're acting like a couple of awkward teenagers despite the fact you're getting married tomorrow.",
  ui_story_5076_50760300_16_dialog_content = "A-Ahem! Fancy meeting you here, Marcela! Feeding one of the wild pigs, huh?",
  ui_story_5076_50760300_17_dialog_content = "L-Ludweiss?",
  ui_story_5076_50760300_18_dialog_content = "A certain commander would be worried to see you here all alone.",
  ui_story_5076_50760300_19_dialog_content = "Huh? Ah!",
  ui_story_5076_50760300_20_dialog_content = "You're right, Adras is probably worried about me! I should go back—",
  ui_story_5076_50760300_21_dialog_content = "What's the rush? Don't you want to tell me what's on your mind first?",
  ui_story_5076_50760300_22_dialog_content = "There's no use hiding it from me. After all, we Caelestites are known for our ability to comprehend emotions. You could even say we're the people of love!",
  ui_story_5076_50760300_23_dialog_content = "Something's been bothering you for the last few days, hasn't it?",
  ui_story_5076_50760300_24_dialog_content = "I see... There really is no hiding things from you.",
  ui_story_5076_50760300_25_dialog_content = "So, what's been troubling you lately?",
  ui_story_5076_50760300_26_dialog_content = "It's nothing really, I just... Maybe it's because the wedding is so close, but I'm feeling a little scared.",
  ui_story_5076_50760300_27_dialog_content = "Scared?",
  ui_story_5076_50760300_28_dialog_content = "A long time ago, I was just like everyone else who had heard the stories of Adras, the people's hero.",
  ui_story_5076_50760300_29_dialog_content = "I always thought meeting a legend like him was impossible, but in the chaos of that day... I saw him.",
  ui_story_5076_50760300_30_dialog_content = "Despite his injuries, he defeated those people so easily and declared that the city was safe.",
  ui_story_5076_50760300_31_dialog_content = "A classic tale of a young maiden falling for a knight in shining armor. Is that when you fell madly in love with him?",
  ui_story_5076_50760300_32_dialog_content = "The opposite, actually—My heart felt unbearably sullen because I couldn't accept that our hero wasn't entirely honest.",
  ui_story_5076_50760300_33_dialog_content = "The hero in our legends was supposed to be invincible, and yet he was covered in countless wounds. It made me wonder just how many times this had happened to him, and if anyone ever bothered to care for him.",
  ui_story_5076_50760300_34_dialog_content = "Before long, I found myself doing exactly that. Caring for him, understanding him...",
  ui_story_5076_50760300_35_dialog_content = "But isn't that a good thing? Treating him like a living, breathing person?",
  ui_story_5076_50760300_36_dialog_content = "But... don't you think I've meddled in his life too much?",
  ui_story_5076_50760300_37_dialog_content = "Because of me, he can't go on an important mission with his fellow soldiers... Is he really willing to abandon his duties like this?",
  ui_story_5076_50760300_38_dialog_content = "Adras seems perfectly happy to me, don't you think?",
  ui_story_5076_50760300_39_dialog_content = "He once told me that even as a child, he was never far from the battlefield. Because of that, he didn't know what it meant to be happy. That's why it fills my heart with joy when I see him playing happily with the children...",
  ui_story_5076_50760300_40_dialog_content = "But I can tell he's not used to living like this, and it seems like he's only doing it because of me.",
  ui_story_5076_50760300_41_dialog_content = "Giving him a home to come back to is a wonderful thing—",
  ui_story_5076_50760300_42_dialog_content = "And yet this normal life is the reason why he started having such terrible nightmares.",
  ui_story_5076_50760300_43_dialog_content = "Adras is... a hero to the people. I'm just worried that I'm holding him back.",
  ui_story_5076_50760300_44_dialog_content = "Ah, but don't worry about it too much. I'm sure it's just the pre-wedding nerves getting to me...",
  ui_story_5076_50760300_45_dialog_content = "Have you mentioned any of this to Adras? No, right?",
  ui_story_5076_50760300_46_dialog_content = "... On the Day of Triumph, the king personally paid him a visit. Some people even suggested erecting a statue of him in the town square.",
  ui_story_5076_50760300_47_dialog_content = "But after that, Adras' heroic exploits came to an end. People slowly began to forget about him, and the matter was left unsettled.",
  ui_story_5076_50760300_48_dialog_content = "I know he doesn't care about fame or glory, but I can't help but feel that he's given up so much because of me.",
  ui_story_5076_50760300_49_dialog_content = "I'm so grateful to him for helping me run this orphanage, but he's still Adras, the people's hero.",
  ui_story_5076_50760300_50_dialog_content = "He's still a shining star, one that burns with great ambitions.",
  ui_story_5076_50760300_51_dialog_content = "Just like I have things only I can do, Adras has things that only he can accomplish.",
  ui_story_5076_50760300_52_dialog_content = "You're not saying these things because you want to leave him, right...?",
  ui_story_5076_50760300_53_dialog_content = "Are you kidding? I'd only hurt him by doing something like that... as well as myself.",
  ui_story_5076_50760300_54_dialog_content = "I just wish that he could be free.",
  ui_story_5076_50760300_55_dialog_content = "If his heart tells him to fight for home and country, then that's exactly what I want him to do. I don't want him to stay here just because of me...",
  ui_story_5076_50760300_56_dialog_content = "Is that what you think? Because as far as I can tell, Adras is still the same hero as he was on that day.",
  ui_story_5076_50760300_57_dialog_content = "He helps the elderly chop firewood, fixes the temple's roof, trains the militia, and finds time to play with the children...",
  ui_story_5076_50760300_58_dialog_content = "He's using every ounce of his strength to do good, and that's why everyone in this town loves him.",
  ui_story_5076_50760300_59_dialog_content = "Isn't that what a hero is supposed to do?",
  ui_story_5076_50760300_60_dialog_content = "But... The threat of the Eclipsites is still very real in this world.",
  ui_story_5076_50760300_61_dialog_content = "This war has cost so many people their homes, and even their families. Adras and I are no exception...",
  ui_story_5076_50760300_62_dialog_content = "I worry that if Adras doesn't put his talents to use, he's going to regret it someday.",
  ui_story_5076_50760300_63_dialog_content = "You should tell him if this really worries you.",
  ui_story_5076_50760300_64_dialog_content = "You won't know each other's thoughts on the matter if you keep bottling up your feelings.",
  ui_story_5076_50760300_65_dialog_content = "Outsiders like us will only ever know him as the invincible commander.",
  ui_story_5076_50760300_66_dialog_content = "You, on the other hand, are the only one who can see the wounds beneath his armor and worry about the death of his ambitions.",
  ui_story_5076_50760300_67_dialog_content = "I'm certain he'll understand if you share your feelings with him.",
  ui_story_5076_50760300_68_dialog_content = "But I'm scared that he'll bury his dreams just to accommodate me.",
  ui_story_5076_50760300_69_dialog_content = "Is that what's been troubling you all along?",
  ui_story_5076_50760300_70_dialog_content = "It's my fault for upsetting you like this.",
  ui_story_5076_50760300_71_dialog_content = "Adras?!",
  ui_story_5076_50760300_72_dialog_content = "N-No, I'm the one who should apologize for worrying you!",
  ui_story_5076_50760300_73_dialog_content = "Oh, Adras. Is this the first time you've failed to make someone feel safe?",
  ui_story_5076_50760300_74_dialog_content = "I lost my home to the Eclipsites a long time ago. Ever since I was a child, I felt nothing but hatred for them, and so I enlisted in the military as soon as I could.",
  ui_story_5076_50760300_75_dialog_content = "Perhaps because of that, I've never been able to understand what it means to live in peace. Even so, it gave me the resolve to protect all that I hold dear.",
  ui_story_5076_50760300_76_dialog_content = "Whenever I slept in my tent, my dreams were filled with the stench of blood.",
  ui_story_5076_50760300_77_dialog_content = "Hatred, rage, and comradery kept me charging into the enemy.",
  ui_story_5076_50760300_78_dialog_content = "There was no end in sight, but I was willing to keep fighting for the sake of those standing behind me.",
  ui_story_5076_50760300_79_dialog_content = "I didn't live and fight for them because I had to, but because I wanted to. So long as there was someone behind me, I refused to fall.",
  ui_story_5076_50760300_80_dialog_content = "Adras...",
  ui_story_5076_50760300_81_dialog_content = "But that day, when I put an end to the rebellion and entered the city—",
  ui_story_5076_50760300_82_dialog_content = "That's when you came into my world. You were just another person in the crowd, keeping a group of orphans safe.",
  ui_story_5076_50760300_83_dialog_content = "But then you ran up to me all of a sudden, scolding me as you cleaned and bandaged my wounds.",
  ui_story_5076_50760300_84_dialog_content = "In that moment, as you told me to hold still and to stop pushing myself so hard—",
  ui_story_5076_50760300_85_dialog_content = "I knew that I had finally found salvation from a life of death and destruction.",
  ui_story_5076_50760300_86_dialog_content = "Do you still remember the dream you gave me that day?",
  ui_story_5076_50760300_87_dialog_content = "If the world ever returns to peace once more, what will the great Adras do?",
  ui_story_5076_50760300_88_dialog_content = "What else can I do?",
  ui_story_5076_50760300_89_dialog_content = "All I know is war—But maybe I can become a traveling bard? In the past, people would practically run back to work whenever they heard me sing.",
  ui_story_5076_50760300_90_dialog_content = "You must have quite a unique voice then!",
  ui_story_5076_50760300_91_dialog_content = "I've never thought about life after the war, so I don't really have any ideas.",
  ui_story_5076_50760300_92_dialog_content = "It looks like planning isn't exactly your strong suit, but don't worry. I'll help you think of something.",
  ui_story_5076_50760300_93_dialog_content = "With your imposing stature, you might do well in sales or negotiations.",
  ui_story_5076_50760300_94_dialog_content = "You're also very strong, so building and repairing structures is worth considering.",
  ui_story_5076_50760300_95_dialog_content = "I'm sure you could become a top-notch baker with your bread-making skills as well.",
  ui_story_5076_50760300_96_dialog_content = "I'm not sure I could list all of your positive traits all at once, but one thing's for certain: your future will be a bright one.",
  ui_story_5076_50760300_97_dialog_content = "My future... won't be bright unless you're in it.",
  ui_story_5076_50760300_98_dialog_content = "What would you do if peace really did return, Marcela?",
  ui_story_5076_50760300_99_dialog_content = "Me? Well... I don't have any lofty aspirations to speak of, to be honest.",
  ui_story_5076_50760300_100_dialog_content = "But in a peaceful world, I'd love to build a small cottage in the countryside and become a wheat farmer... And maybe adopt a few children too.",
  ui_story_5076_50760300_101_dialog_content = "And if you were there with me, I'd take you and the children to harvest the fields with me in the fall.",
  ui_story_5076_50760300_102_dialog_content = "I'd be happy to spend those peaceful days with you, watching golden fields of wheat in the warm glow of the sun—",
  ui_story_5076_50760300_103_dialog_content = "Then that's my dream as well.",
  ui_story_5076_50760300_104_dialog_content = "Marcela, my past is far from a happy one, so I have very little faith in any god. Even so, I swear to you—",
  ui_story_5076_50760300_105_dialog_content = "That I, Adras, will never stop fighting for our golden dream. Nor will I ever leave your side.",
  ui_story_5076_50760300_106_dialog_content = "We made that promise together, but you've been suffering so much because of it.",
  ui_story_5076_50760300_107_dialog_content = "In the past, I didn't care if I lived or died on the battlefield. I fought for the people I wanted to protect with almost no regard for my own safety.",
  ui_story_5076_50760300_108_dialog_content = "But after I fell for you, I started remembering your face even in the midst of battle. Every encounter with the Eclipsites made me worry that I wouldn't make it back to you.",
  ui_story_5076_50760300_109_dialog_content = "Once I had someone to care about, I apparently lost the ability to fight like a demon. At one point, I wondered if it was making me weak—",
  ui_story_5076_50760300_110_dialog_content = "But then I came home to you and the children. They pestered me with questions and begged me to play with them, all without the faintest hint of pain or hatred in their eyes.",
  ui_story_5076_50760300_111_dialog_content = "What I had been protecting all along... That was when it first became clear to me.",
  ui_story_5076_50760300_112_dialog_content = "Adras...",
  ui_story_5076_50760300_113_dialog_content = "I didn't become weaker because of you, Marcela. I grew stronger.",
  ui_story_5076_50760300_114_dialog_content = "I was finally afraid of death, and that fear made me want to keep living so I could stay at your side.",
  ui_story_5076_50760300_115_dialog_content = "After a long and painful life, I finally understood what it meant to live.",
  ui_story_5076_50760300_116_dialog_content = "I don't need statues or everlasting glory. In fact, I'd be delighted if everyone completely forgot about me!",
  ui_story_5076_50760300_117_dialog_content = "If that day ever comes, then the world will definitely be at peace.",
  ui_story_5076_50760300_118_dialog_content = "All I want is to keep making memories with you, no matter how ordinary they may be.",
  ui_story_5076_50760300_119_dialog_content = "Adras... I'm so sorry! I don't know what I was thinking.",
  ui_story_5076_50760300_120_dialog_content = "I never stopped to consider your feelings.",
  ui_story_5076_50760300_121_dialog_content = "You don't need to worry about that, Marcela. For our dreams and memories to come, I'll never give up on myself.",
  ui_story_5076_50760300_122_dialog_content = "If the world ever needs me someday, then I'll step onto the battlefield once more.",
  ui_story_5076_50760300_123_dialog_content = "Because I know that a world as beautiful as this deserves to be protected—",
  ui_story_5076_50760300_124_dialog_content = "So please don't worry, Marcela.",
  ui_story_5076_50760300_125_dialog_content = "With the gods and Ludweiss as our witnesses, please let go of your fears and marry me!",
  ui_story_5076_50760300_126_dialog_content = "I... I will!",
  ui_story_5076_50760300_127_dialog_content = "<color=#e8d9bb>The next day, the city hosts a grand wedding for the hero, and everyone showers heartfelt blessings upon the couple.</color>",
  ui_story_5076_50760300_128_dialog_content = "As we work towards our dream, let's keep making beautiful memories together.",
  ui_story_5076_50760300_129_dialog_content = "I promise to cherish every single wonderful moment of our lives—",
  ui_story_5076_50760300_130_dialog_content = "I love you, Marcela.",
  ui_story_5076_50760300_131_dialog_content = "As do I, my dear Adras—",
  ui_story_5076_50760300_132_dialog_content = "I love you.",
  ui_story_5076_50760400_1_dialog_content = "... That's basically how things are at the front; the expeditionary force is facing tough times and will return to the capital shortly.",
  ui_story_5076_50760400_2_dialog_content = "When General Achilles returns, I'll put in for my immediate return to the line of duty.",
  ui_story_5076_50760400_3_dialog_content = "I will fight at everyone's side in the next battle.",
  ui_story_5076_50760400_4_dialog_content = "But, Commander, per the General's orders, your vacation is not over yet.",
  ui_story_5076_50760400_5_dialog_content = "And you don't have any heirs yet, and General Achilles won't approve of you going to the frontline.",
  ui_story_5076_50760400_6_dialog_content = "Marcela's health won't permit us to have a child of our own... Plus, the kids at the orphanage are family to us as well—",
  ui_story_5076_50760400_7_dialog_content = "Oh? Do we have a visitor?",
  ui_story_5076_50760400_8_dialog_content = "Augustine! What good news have you brought us today?",
  ui_story_5076_50760400_9_dialog_content = "It's been a while, madam, and you've become even more beautiful.",
  ui_story_5076_50760400_10_dialog_content = "I just brought some news from the capital. It's been a while since we've seen Commander, and we all miss him.",
  ui_story_5076_50760400_11_dialog_content = "I'm sure Adras misses all of you as well. Do you need him to return sooner than expected?",
  ui_story_5076_50760400_12_dialog_content = "Everyone would surely be overjoyed—but, madam, we dare not steal the Commander away from you just like that.",
  ui_story_5076_50760400_13_dialog_content = "It's getting late, Commander Adras. I should also head back to the capital now.",
  ui_story_5076_50760400_14_dialog_content = "Take care. I'll be along soon enough.",
  ui_story_5076_50760400_15_dialog_content = "Take good care too, both of you.",
  ui_story_5076_50760400_16_dialog_content = "Adras, is the expedition force...",
  ui_story_5076_50760400_17_dialog_content = "They're fine, Marcela. Don't listen to the rumors.",
  ui_story_5076_50760400_18_dialog_content = "You want to go back, do you?",
  ui_story_5076_50760400_19_dialog_content = "... Try this. I've been working on a new brewing technique.",
  ui_story_5076_50760400_20_dialog_content = "And just where exactly did you learn—Mmm! It's so sweet!",
  ui_story_5076_50760400_21_dialog_content = "And it doesn't burn at all! I love it!",
  ui_story_5076_50760400_22_dialog_content = "I learned it from the priests.",
  ui_story_5076_50760400_23_dialog_content = "So you've been helping with the temple's repairs to steal their wine-making techniques?",
  ui_story_5076_50760400_24_dialog_content = "That doesn't sound like you at all, o mighty hero.",
  ui_story_5076_50760400_25_dialog_content = "They willingly shared their knowledge with me for your information. They also said it's good for the body, so I made two barrels of it just for you.",
  ui_story_5076_50760400_26_dialog_content = "The ingredients I used were also a gift from others, a token of appreciation for everything you've done for them.",
  ui_story_5076_50760400_27_dialog_content = "You've been accepting gifts for me when I'm not around? It's one thing for them to thank you for helping around the town, but what have I done?",
  ui_story_5076_50760400_28_dialog_content = "You should just accept their gifts. Returning them would only embarrass everyone.",
  ui_story_5076_50760400_29_dialog_content = "Well thanks to your charisma, our house is full to bursting with gifts.",
  ui_story_5076_50760400_30_dialog_content = "You think I have charisma?",
  ui_story_5076_50760400_31_dialog_content = "That's right!",
  ui_story_5076_50760400_32_dialog_content = "No, I think those people are just really kind. The children are being especially helpful now as well. Just this afternoon, they went with me to harvest the fields near the orphanage.",
  ui_story_5076_50760400_33_dialog_content = "... So I know you'll be taken care of even if I'm not around for some while.",
  ui_story_5076_50760400_34_dialog_content = "I've always been good with people, Adras. Or have you forgotten?",
  ui_story_5076_50760400_35_dialog_content = "I know that there are plenty of people who need you besides us. Our neighbors know that as well, which is why they've been so nice lately.",
  ui_story_5076_50760400_36_dialog_content = "They don't want to keep you all to themselves here, because they know you have more important things to do.",
  ui_story_5076_50760400_37_dialog_content = "The flames of war have cost so many people their homes. At the very least, I want to protect this peaceful corner of our world.",
  ui_story_5076_50760400_38_dialog_content = "I promise I'll be back as soon as I can, Marcela.",
  ui_story_5076_50760400_39_dialog_content = "Don't worry. We'll be here waiting for you.",
  ui_story_5076_50760400_40_dialog_content = "We'll look after our home in your absence... So that our hero always has a place where he can return.",
  ui_story_5076_50760400_41_dialog_content = "I'll make it safely back to you, my dear Marcela—",
  ui_story_5076_50760400_42_dialog_content = "For you and for these kind people, I'll rid our world of the evil that threatens us.",
  ui_story_5076_50760400_43_dialog_content = "And when I return, we'll meet again in a sea of golden wheat.",
  ui_story_5076_50760400_44_dialog_content = "Then it's a promise.",
  ui_story_5076_50760400_45_dialog_content = "Adras?",
  ui_story_5076_50760400_46_dialog_content = "Ludweiss? What are you doing here? Did you come here with the expedition force?",
  ui_story_5076_50760400_47_dialog_content = "It's complicated, and I'm not sure where to start... Still, I'm glad to see you again.",
  ui_story_5076_50760400_48_dialog_content = "I'm sure Achilles will be happy to see you too. Come with me.",
  ui_story_5076_50760400_49_dialog_content = "Is that... Commander Adras?",
  ui_story_5076_50760400_50_dialog_content = "Commander Adras is back?",
  ui_story_5076_50760400_51_dialog_content = "Commander Adras!",
  ui_story_5076_50760400_52_dialog_content = "Commander Adras, are you returning to duty?",
  ui_story_5076_50760400_53_dialog_content = "How... How did everybody end up so wounded?",
  ui_story_5076_50760400_54_dialog_content = "We...",
  ui_story_5076_50760400_55_dialog_content = "Dominic! Bruno! Where are you?",
  ui_story_5076_50760400_56_dialog_content = "Commander, it's really good to see you.",
  ui_story_5076_50760400_57_dialog_content = "Anthony... What happened to your eyes?",
  ui_story_5076_50760400_58_dialog_content = "Guess I'm getting on in years after all. Had a momentary lapse, and a sneaky Eclipsite took one of them from me.",
  ui_story_5076_50760400_59_dialog_content = "Sorry, Commander, I've let Dominick down. It was all because I lost my shield, and to save me, he...",
  ui_story_5076_50760400_60_dialog_content = "What on earth happened during the expedition?",
  ui_story_5076_50760400_61_dialog_content = "Adras? Is that you?",
  ui_story_5076_50760400_62_dialog_content = "It really is you... Everyone must be so relieved to see you, Adras.",
  ui_story_5076_50760400_63_dialog_content = "General? You look completely exhausted. What happened to the...",
  ui_story_5076_50760400_64_dialog_content = "We came across a shadowy abyss in the far north.",
  ui_story_5076_50760400_65_dialog_content = "Countless, powerful Eclipsites kept coming out of it... In terms of strength and numbers, they were like nothing we'd ever seen before.",
  ui_story_5076_50760400_66_dialog_content = "I failed to properly command our troops, and so we suffered devastating casualties.",
  ui_story_5076_50760400_67_dialog_content = "During our retreat, Ludweiss was injured by the power of the Eclipsites as well.",
  ui_story_5076_50760400_68_dialog_content = "Don't look so worried, Adras. Thankfully, the Silent Saintess was there to save me and make me good as new!",
  ui_story_5076_50760400_69_dialog_content = "I had never seen Eclipsites like those. They aren't something we can handle right now.",
  ui_story_5076_50760400_70_dialog_content = "And some of them... Are far beyond our comprehension. I can't even imagine a way to defeat those monstrosities.",
  ui_story_5076_50760400_71_dialog_content = "We weren't able to eradicate them back in the north, and now they're marching towards the royal capital... Curse them all!",
  ui_story_5076_50760400_72_dialog_content = "Put your mind at ease, for now, General Achilles. I'm ready to return to the front lines and fight on everyone's side.",
  ui_story_5076_50760400_73_dialog_content = "We were just caught off-guard last time. With the right preparations, I'm sure we can put a stop to their evil.",
  ui_story_5076_50760400_74_dialog_content = "Adras' right. We cannot afford to lose to those things.",
  ui_story_5076_50760400_75_dialog_content = "To route the invading Eclipsite horde, I believe it's best to let me back to the force and start combat preparations together.",
  ui_story_5076_50760400_76_dialog_content = "That way, we can halt their march before they reach our home.",
  ui_story_5076_50760400_77_dialog_content = "Adras... You really have changed.",
  ui_story_5076_50760400_78_dialog_content = "How have you been lately?",
  ui_story_5076_50760400_79_dialog_content = "I've been well. Our neighbors have been taking good care of us out there.",
  ui_story_5076_50760400_80_dialog_content = "I finally understood what you meant when you told me about the \"beauty of peace.\"",
  ui_story_5076_50760400_81_dialog_content = "Won't you fear death if I send you to the front lines again?",
  ui_story_5076_50760400_82_dialog_content = "You aren't the same man anymore. Can you really abandon your sense of self-preservation like before?",
  ui_story_5076_50760400_83_dialog_content = "I can't, and that's because... I understand the meaning of fear now.",
  ui_story_5076_50760400_84_dialog_content = "But even so, I have to protect those fields of golden wheat and the people who call that place home.",
  ui_story_5076_50760400_85_dialog_content = "Which is why I have to survive.",
  ui_story_5076_50760400_86_dialog_content = "I'll survive along with my comrades-in-arms, and we'll return to our loved ones together.",
  ui_story_5076_50760400_87_dialog_content = "I see... That's a relief.",
  ui_story_5076_50760400_88_dialog_content = "You're much stronger now than in the past.",
  ui_story_5076_50760400_89_dialog_content = "I'm confident I can trust your shield with my life, just like before.",
  ui_story_5076_50760400_90_dialog_content = "For the glory of our kingdom, we'll ride into battle once more.",
  ui_story_5076_50760400_91_dialog_content = "Looks like you're feeling a lot better now. I didn't realize Adras was such a powerful speaker!",
  ui_story_5076_50760400_92_dialog_content = "Guess Adras really is a hero to everyone.",
  ui_story_5076_50760400_93_dialog_content = "Agreed. If everyone in our army was like Adras... Even the strongest Eclipsites wouldn't stand a chance against us.",
  ui_story_5076_50760400_94_dialog_content = "I wouldn't mind being a part of that army!",
  ui_story_5076_50760400_95_dialog_content = "I should begin preparations immediately. If you'll excuse me.",
  ui_story_5076_50760400_96_dialog_content = "Adras.",
  ui_story_5076_50760400_97_dialog_content = "Yes?",
  ui_story_5076_50760400_98_dialog_content = "Cherish everything you have in life.",
  ui_story_5076_50760400_99_dialog_content = "I have no intention of doing otherwise, sir.",
  ui_story_5076_50760400_100_dialog_content = "After all, I made a promise to her.",
  ui_story_5076_50760501_1_dialog_content = "This should be the last of it. I don't think there's anything else to move out of the orphanage.",
  ui_story_5076_50760501_2_dialog_content = "Are these... Adras' wooden training swords?",
  ui_story_5076_50760501_3_dialog_content = "The children keep asking to learn swordsmanship so they can protect the town. Bringing these back might get them to calm down.",
  ui_story_5076_50760501_4_dialog_content = "Ah, if only I could bring this mural of our wedding day. It was such a precious moment...",
  ui_story_5076_50760501_5_dialog_content = "I never thought the Eclipsites would reach this place.",
  ui_story_5076_50760501_6_dialog_content = "How much longer will the orphanage stay closed? I wish I could see those happy kids running through the wheat fields one more time.",
  ui_story_5076_50760501_7_dialog_content = "Everything will be okay. While Adras and the others fight on the front lines, we'll fight to keep this city safe.",
  ui_story_5076_50760501_8_dialog_content = "Sorry that I'm still not recovered... Otherwise, I'd be out there helping everybody too.",
  ui_story_5076_50760501_9_dialog_content = "You don't need to apologize, Ludweiss. You've already done so much for us.",
  ui_story_5076_50760501_10_dialog_content = "Your timely warnings have been keeping us safe these last few days.",
  ui_story_5076_50760501_11_dialog_content = "Are the city's defenses being repaired now?",
  ui_story_5076_50760501_12_dialog_content = "Yes. We're also building a shelter beneath the temple and an escape tunnel.",
  ui_story_5076_50760501_13_dialog_content = "Everyone's working so hard together, and encouraging each other the entire way.",
  ui_story_5076_50760501_14_dialog_content = "The people Adras trained have also formed a small militia. I can tell that they're all full of hope.",
  ui_story_5076_50760501_15_dialog_content = "It's all thanks to you, Marcela... Before reinforcements arrived, you were the one who gave them hope and spurred them into action.",
  ui_story_5076_50760501_16_dialog_content = "I was just doing my small part. They're the ones who did all of the work—",
  ui_story_5076_50760501_17_dialog_content = "Come on, let's bring these things back for the children.",
  ui_story_5076_50760501_18_dialog_content = "Did Achilles send you to deliver this letter? What's the situation on the front lines?",
  ui_story_5076_50760501_19_dialog_content = "Commander Adras, with his legion, is pushing back the massive attack on the capital and has secured a series of victories.",
  ui_story_5076_50760501_20_dialog_content = "His Majesty ordered him to assist General Achilles in leading the troops to pursue and wipe out the Eclipsites.",
  ui_story_5076_50760501_21_dialog_content = "The commander assigned here to defend this city is a follower of High Priest Lucius. That's all the message I'm supposed to deliver.",
  ui_story_5076_50760501_22_dialog_content = "But besides that, Miss Ludweiss, I've got some intel...",
  ui_story_5076_50760501_23_dialog_content = "It seems High Priest Lucius is vying for the merit, intending to concentrate forces to attack the flanks of the Eclipsites. He has already left and redeployed the defending forces along the way!",
  ui_story_5076_50760501_24_dialog_content = "In other words, it's unlikely that this city will receive any military support. Is that it?",
  ui_story_5076_50760501_25_dialog_content = "... I'll stay, even if it means laying down my life to protect the civilians in the city.",
  ui_story_5076_50760501_26_dialog_content = "Don't say that!",
  ui_story_5076_50760501_27_dialog_content = "Life is the most precious thing in this world! Don't talk about it like it's anything less than that!",
  ui_story_5076_50760501_28_dialog_content = "Y-Yes! I apologize for that!",
  ui_story_5076_50760501_29_dialog_content = "You have military experience. I'll leave command of the militia in your hands.",
  ui_story_5076_50760501_30_dialog_content = "I have to...",
  ui_story_5076_50760501_31_dialog_content = "Have to do what, Ludweiss?",
  ui_story_5076_50760501_32_dialog_content = "Marcela...?",
  ui_story_5076_50760501_33_dialog_content = "I'm going to help defend the city walls.",
  ui_story_5076_50760501_34_dialog_content = "So you heard everything?",
  ui_story_5076_50760501_35_dialog_content = "Yes, but I won't tell anyone about it just yet. You two have to do the same.",
  ui_story_5076_50760501_36_dialog_content = "I'm going to defend this place with everyone. This is our home, as well as the home of the great hero Adras.",
  ui_story_5076_50760501_37_dialog_content = "I have to leave for a while, Marcela.",
  ui_story_5076_50760501_38_dialog_content = "Then please be careful... And don't push yourself too hard.",
  ui_story_5076_50760501_39_dialog_content = "Where exactly are you going?",
  ui_story_5076_50760501_40_dialog_content = "The Eclipsite horde will be here soon. I have to do something that only us Caelestites can do...",
  ui_story_5076_50760501_41_dialog_content = "I'll use my powers to slip through their ranks and deliver a message to Adras.",
  ui_story_5076_50760501_42_dialog_content = "But that's way too dangerous!",
  ui_story_5076_50760501_43_dialog_content = "Adras needs to know. For your sake, and for the sake of this entire city.",
  ui_story_5076_50760501_44_dialog_content = "We could never repay you for all that you do for us, Ludweiss...",
  ui_story_5076_50760501_45_dialog_content = "Please be careful.",
  ui_story_5076_50760501_46_dialog_content = "I'm just a wanderer who lost her way. It was only thanks to everyone here that I remembered the beauty of Eraveil, my home.",
  ui_story_5076_50760501_47_dialog_content = "I'll make sure to bring Adras here. Until then, stay on your guard and don't give up hope.",
  ui_story_5076_50760501_48_dialog_content = "(I'll definitely make it—)",
  ui_story_5076_50760501_49_dialog_content = "(No matter how far or how difficult the road may be—)",
  ui_story_5076_50760501_50_dialog_content = "<color=#e8d9bb>Eclipsites from the far north have infested the entire continent, setting even the wilderness ablaze.</color>",
  ui_story_5076_50760501_51_dialog_content = "<color=#e8d9bb>The fire devastates the homes of the civilians, and the once-serene wheat fields are almost entirely burnt.</color>",
  ui_story_5076_50760501_52_dialog_content = "Adras!",
  ui_story_5076_50760501_53_dialog_content = "Huh? What's with all the shouting?",
  ui_story_5076_50760501_54_dialog_content = "Adras! I... I finally found you...",
  ui_story_5076_50760501_55_dialog_content = "Ludweiss? What are you doing here? Those burns... You're seriously hurt!",
  ui_story_5076_50760501_56_dialog_content = "Call a medic, Anthony!",
  ui_story_5076_50760501_57_dialog_content = "Forget about that! Y-You have to come with me!",
  ui_story_5076_50760501_58_dialog_content = "Lucius transferred all of his forces out of the city! He left Marcela and the others to fend for themselves!",
  ui_story_5076_50760501_59_dialog_content = "What did you say?",
  ui_story_5076_50760501_60_dialog_content = "Marcela, I...",
  ui_story_5076_50760501_61_dialog_content = "Drat! We were just about to launch a decisive counterattack!",
  ui_story_5076_50760501_62_dialog_content = "As acting commander, I can't just abandon my soldiers.",
  ui_story_5076_50760501_63_dialog_content = "Go, Adras.",
  ui_story_5076_50760501_64_dialog_content = "But General—",
  ui_story_5076_50760501_65_dialog_content = "The enemy is as good as dead. You and the Northwind Legion have already done enough for the kingdom.",
  ui_story_5076_50760501_66_dialog_content = "Our main forces should be the ones protecting your home, but unfortunately... You and your men will have to make this journey alone.",
  ui_story_5076_50760501_67_dialog_content = "That's an order.",
  ui_story_5076_50760501_68_dialog_content = "General Achilles... understood.",
  ui_story_5076_50760501_69_dialog_content = "Are you sure you want to come with me, Ludweiss? Our army has a number of capable medics.",
  ui_story_5076_50760501_70_dialog_content = "If you're not able to make the march, you can always stay here and recover.",
  ui_story_5076_50760501_71_dialog_content = "No, I have to go back with you and make sure Marcela is okay.",
  ui_story_5076_50760501_72_dialog_content = "I promised I'd bring you back to her.",
  ui_story_5076_50760501_73_dialog_content = "Then, let's get going.",
  ui_story_5076_50760501_74_dialog_content = "Soldiers of the Northwind Legion! Heed my call—",
  ui_story_5076_50760501_75_dialog_content = "<color=#e8d9bb>His resounding voice echoes through the tents, and the soldiers respond in unison.</color>",
  ui_story_5076_50760501_76_dialog_content = "<color=#e8d9bb>Soldiers, whose homeland has been protected by their commander countless times, finally get to defend their commander's home.</color>",
  ui_story_5076_50760501_77_dialog_content = "There's no end to them—out of my way!!!",
  ui_story_5076_50760501_78_dialog_content = "Why are there so many Eclipsites beneath the city?",
  ui_story_5076_50760501_79_dialog_content = "Are all of them gathering here?",
  ui_story_5076_50760501_80_dialog_content = "Just how many soldiers has Lucius withdrawn from the fight? How many lives have been lost because of him?!",
  ui_story_5076_50760501_81_dialog_content = "Keep calm, Adras. We're near to the city—",
  ui_story_5076_50760501_82_dialog_content = "You've been leaving troops in every town we pass. That's why it feels like there are even more enemies to fight now.",
  ui_story_5076_50760501_83_dialog_content = "We're not moving fast enough... I promised I'd protect them all! I gave them my word!",
  ui_story_5076_50760501_84_dialog_content = "I saw it! Commander Adras, the city walls are intact, and it seems the city gate has just been breached.",
  ui_story_5076_50760501_85_dialog_content = "The people are taking shelter in the temple, Adras.",
  ui_story_5076_50760501_86_dialog_content = "There's an escape tunnel under it. If they can't defend the temple gates, they can use that tunnel to escape behind the city.",
  ui_story_5076_50760501_87_dialog_content = "Dieter, Vivia, take a team of knights and head to the city's outskirts. Search for survivors and wipe out any Eclipsites roaming the area.",
  ui_story_5076_50760501_88_dialog_content = "Quintas, form a phalanx and flank the enemy from either side. Don't let a single Eclipsite escape.",
  ui_story_5076_50760501_89_dialog_content = "Everyone else, come with me. We're striking at their rear and forcing our way into the city!",
  ui_story_5076_50760501_90_dialog_content = "Stay close, Ludweiss.",
  ui_story_5076_50760501_91_dialog_content = "<color=#FFB400>To battle—!!!</color>",
  ui_story_5076_50760501_92_dialog_content = "<color=#FFB400>Wipe out every last one of these filthy Eclipsites!</color>",
  ui_story_5076_50760501_93_dialog_content = "Commander, the Temple has not fallen, and militia members are still defending inside the main hall!",
  ui_story_5076_50760501_94_dialog_content = "Just a little faster—",
  ui_story_5076_50760501_95_dialog_content = "Wait for me, Adras!",
  ui_story_5076_50760501_96_dialog_content = "Ouch, is it my old wound? Why is it acting up now of all times...",
  ui_story_5076_50760501_97_dialog_content = "No, there's something wrong... Something in my head...",
  ui_story_5076_50760501_98_dialog_content = "Adras...",
  ui_story_5076_50760502_1_dialog_content = "It's Adras!",
  ui_story_5076_50760502_2_dialog_content = "Adras has come to our rescue!",
  ui_story_5076_50760502_3_dialog_content = "Hey, Adras!",
  ui_story_5076_50760502_4_dialog_content = "You're all safe now, so please remain calm. We've managed to secure an escape route.",
  ui_story_5076_50760502_5_dialog_content = "Is everyone alright? Have there been any casualties?",
  ui_story_5076_50760502_6_dialog_content = "Are there any other areas in need of support?",
  ui_story_5076_50760502_7_dialog_content = "No, Commander Adras, we're the rearguard; others have already escaped through the passage.",
  ui_story_5076_50760502_8_dialog_content = "All thanks to Marcela; she motivated us to defend the city, and that's why we could hold on for these days.",
  ui_story_5076_50760502_9_dialog_content = "If you had come here any later, everyone might already have...",
  ui_story_5076_50760502_10_dialog_content = "Marcela...? Where is she now? Did she already escape?",
  ui_story_5076_50760502_11_dialog_content = "Huh? You didn't come across Marcela on your way here?",
  ui_story_5076_50760502_12_dialog_content = "To buy time for everyone's retreat, she led the vanguard near the Temple to distract the Eclipsites...",
  ui_story_5076_50760502_13_dialog_content = "No... No...",
  ui_story_5076_50760502_14_dialog_content = "Don't scare me like this, my love—",
  ui_story_5076_50760502_15_dialog_content = "Wait, Adras! Let me try to sense her location!",
  ui_story_5076_50760502_16_dialog_content = "Please, Ludweiss...",
  ui_story_5076_50760502_17_dialog_content = "There's no need for the rest of you to follow me! Retreat and defend the city's civilians—",
  ui_story_5076_50760502_18_dialog_content = "I can't sift through all of the chaotic thoughts and feelings. All I can tell is that there are Eclipsites gathering to the east of the temple.",
  ui_story_5076_50760502_19_dialog_content = "Out of my way, you rotten monsters!",
  ui_story_5076_50760502_20_dialog_content = "Faster! I need to move faster!!!",
  ui_story_5076_50760502_21_dialog_content = "This place—",
  ui_story_5076_50760502_22_dialog_content = "The people on the ground were with the militia. What a horrible sight...",
  ui_story_5076_50760502_23_dialog_content = "They managed to kill plenty of Eclipsites just up ahead too.",
  ui_story_5076_50760502_24_dialog_content = "Unfortunately, this place is beyond saving—",
  ui_story_5076_50760502_25_dialog_content = "Ah! No... it's Augustine... This can't be.",
  ui_story_5076_50760502_26_dialog_content = "Brave and honorable soldiers... May your souls finally know peace.",
  ui_story_5076_50760502_27_dialog_content = "... Rotten Eclipsites.",
  ui_story_5076_50760502_28_dialog_content = "Marcela! Can you hear me?!",
  ui_story_5076_50760502_29_dialog_content = "Don't worry, I'm coming for you!",
  ui_story_5076_50760502_30_dialog_content = "(N-No—)",
  ui_story_5076_50760502_31_dialog_content = "Who? Who's there?",
  ui_story_5076_50760502_32_dialog_content = "(Someone's in my head, speaking to me... Is it because of my injuries from before?)",
  ui_story_5076_50760502_33_dialog_content = "(You have to wake up—)",
  ui_story_5076_50760502_34_dialog_content = "(Don't watch until the end—)",
  ui_story_5076_50760502_35_dialog_content = "What?",
  ui_story_5076_50760502_36_dialog_content = "<size=40>No... Noooo!!!</size>",
  ui_story_5076_50760502_37_dialog_content = "Adras???",
  ui_story_5076_50760502_38_dialog_content = "Argh, my head... It's killing me.",
  ui_story_5076_50760502_39_dialog_content = "<size=40>Don't scare me like this, Marcela—</size>",
  ui_story_5076_50760502_40_dialog_content = "<color=#FFB400><size=45>Marcela!!!</size></color>",
  ui_story_5076_50760502_41_dialog_content = "What's going on...",
  ui_story_5076_50760502_42_dialog_content = "Adras, Marcela...",
  ui_story_5076_50760502_43_dialog_content = "Wait for me...",
  ui_story_5076_50760502_44_dialog_content = "!!!",
  ui_story_5076_50760502_45_dialog_content = "Thanks be to the gods—",
  ui_story_5076_50760502_46_dialog_content = "For not stealing my beloved from me, my sweet Marcela—",
  ui_story_5076_50760502_47_dialog_content = "Marcela! It's me, I'm right here! I came back, just like I promised.",
  ui_story_5076_50760502_48_dialog_content = "Don't worry, we're going home now...",
  ui_story_5076_50760502_49_dialog_content = "(Memories are—)",
  ui_story_5076_50760502_50_dialog_content = "<color=#FFB400>(A curse.)</color>",
  ui_story_5076_50760502_51_dialog_content = "(But for now... Please don't get in the way of their reunion.)",
  ui_story_5076_50760502_52_dialog_content = "That voice in my head... Who are you...?",
  ui_story_5076_50760502_53_dialog_content = "You're finally back, Adras.",
  ui_story_5076_50760502_54_dialog_content = "I waited so long... for you.",
  ui_story_5076_50760502_55_dialog_content = "Save your strength, my love. I'll have a healer tend to your wounds before we go home.",
  ui_story_5076_50760502_56_dialog_content = "Those two barrels of wine you left me... I shared them with everyone.",
  ui_story_5076_50760502_57_dialog_content = "They all said it was delicious, and that its sweetness made them feel so happy.",
  ui_story_5076_50760502_58_dialog_content = "That's why we weren't afraid, not even for a moment—",
  ui_story_5076_50760502_59_dialog_content = "Adras... whenever I think of you, my heart fills with hope.",
  ui_story_5076_50760502_60_dialog_content = "Thank you for keeping your promise.",
  ui_story_5076_50760600_1_dialog_content = "<color=#e8d9bb>The city, once ravaged by monsters, now embraces the days of reconstruction. The faith coming from heroes fills its residents with hope.</color>",
  ui_story_5076_50760600_2_dialog_content = "<color=#e8d9bb>Yet, amid this flourishing atmosphere, many still find themselves without a home.</color>",
  ui_story_5076_50760600_3_dialog_content = "Be careful when moving the wreckage, and keep an eye out for pedestrians! If you need help, ask the Legion soldiers!",
  ui_story_5076_50760600_4_dialog_content = "Yes, sir.",
  ui_story_5076_50760600_5_dialog_content = "Let's go.",
  ui_story_5076_50760600_6_dialog_content = "... Sure.",
  ui_story_5076_50760600_7_dialog_content = "Adras, what...?",
  ui_story_5076_50760600_8_dialog_content = "It's nothing. We're just going for a walk.",
  ui_story_5076_50760600_9_dialog_content = "\"We\"? Oh... Oh! Please don't worry too much; we'll soon complete the reconstruction.",
  ui_story_5076_50760600_10_dialog_content = "Marcela? I thought you were friends with that man... Why didn't you at least say hello?",
  ui_story_5076_50760600_11_dialog_content = "... It's fine. Let's just keep going.",
  ui_story_5076_50760600_12_dialog_content = "Where would you like to go? The temple, maybe?",
  ui_story_5076_50760600_13_dialog_content = "No! Anywhere but the temple! I'm... still afraid of that place.",
  ui_story_5076_50760600_14_dialog_content = "That's okay, we can go somewhere else. Why don't we pay a visit to the children? They've been doing well, but I'm sure you're still worried about them.",
  ui_story_5076_50760600_15_dialog_content = "I found him, Achilles. He's over here.",
  ui_story_5076_50760600_16_dialog_content = "...",
  ui_story_5076_50760600_17_dialog_content = "Adras... Are you alright?",
  ui_story_5076_50760600_18_dialog_content = "... Ludweiss?",
  ui_story_5076_50760600_19_dialog_content = "The battle is over, Adras. Why are you still here?",
  ui_story_5076_50760600_20_dialog_content = "There's no one left to defend this place. I have to protect the people here.",
  ui_story_5076_50760600_21_dialog_content = "Ah! Don't be afraid, Marcela! It's just General Achilles.",
  ui_story_5076_50760600_22_dialog_content = "Sorry, but the battle really took its toll on Marcela. Please forgive her if she's too afraid to say hello.",
  ui_story_5076_50760600_23_dialog_content = "Adras, Marcela is—",
  ui_story_5076_50760600_24_dialog_content = "Achilles!",
  ui_story_5076_50760600_25_dialog_content = "What is it? You two are acting so strangely, especially you Ludweiss. Why haven't you come to visit Marcela more often?",
  ui_story_5076_50760600_26_dialog_content = "... Look at me, Adras.",
  ui_story_5076_50760600_27_dialog_content = "Yes? Oh, before I forget... Have the Eclipsites at the front lines been taken care of? Can we finally enjoy some peace again?",
  ui_story_5076_50760600_28_dialog_content = "We managed to push the Eclipsites back to the north but still can't do anything about the abyss we found up there.",
  ui_story_5076_50760600_29_dialog_content = "Are you willing to return to the fight, Adras?",
  ui_story_5076_50760600_30_dialog_content = "Of course. It's my duty to protect my home and country, after all.",
  ui_story_5076_50760600_31_dialog_content = "You're willing to let me return to battle, right Marcela? Don't worry, I'll always keep my promise to you.",
  ui_story_5076_50760600_32_dialog_content = "...",
  ui_story_5076_50760600_33_dialog_content = "Ludweiss, you once told me that love is the source of a Caelestite's power. Driven by the strength of emotions, you and your people have accomplished extraordinary things.",
  ui_story_5076_50760600_34_dialog_content = "Tell me, is there any way to extract an Aurorian's emotions and preserve them?",
  ui_story_5076_50760600_35_dialog_content = "What exactly are you proposing?",
  ui_story_5076_50760600_36_dialog_content = "Right now, Adras needs to be spurred into action by hatred and revenge. However, I don't want the love in his heart to be consumed by it.",
  ui_story_5076_50760600_37_dialog_content = "What in the world are you two talking about?",
  ui_story_5076_50760600_38_dialog_content = "Ludweiss, I need to know if there's a way to extract that love and keep it safe.",
  ui_story_5076_50760600_39_dialog_content = "I understand... I'll think of something.",
  ui_story_5076_50760600_40_dialog_content = "Are you willing to lend me your shield and strength again, Adras?",
  ui_story_5076_50760600_41_dialog_content = "Of course I am!",
  ui_story_5076_50760600_42_dialog_content = "How much do you hate the Eclipsites? Are you willing to dedicate your life and all that you are to their complete annihilation?",
  ui_story_5076_50760600_43_dialog_content = "The Eclipsites... That goes without saying! I have nothing but hatred in my heart for them...",
  ui_story_5076_50760600_44_dialog_content = "Even with the weight of eternity on your shoulders, do you swear to fight this evil with all your heart until nothing remains?",
  ui_story_5076_50760600_45_dialog_content = "I... I swear.",
  ui_story_5076_50760600_46_dialog_content = "Then, on behalf of our proud soldiers and myself, our lives are in your capable hands once more.",
  ui_story_5076_50760600_47_dialog_content = "Welcome back to the line of duty, Adras.",
  ui_story_5076_50760600_48_dialog_content = "Welcome back to the war.",
  ui_story_5076_50760600_49_dialog_content = "So where should I begin?",
  ui_story_5076_50760600_50_dialog_content = "To eradicate the abyss in the north, the royal court proposed a new method for enhancing our powers.",
  ui_story_5076_50760600_51_dialog_content = "A project which will consume us, but not before we purge our world of all evil.",
  ui_story_5076_50760600_52_dialog_content = "And the name of that project is—",
  ui_story_5076_50760600_53_dialog_content = "<color=#FFB400>The Silent Hunters.</color>",
  ui_story_5076_50760701_1_dialog_content = "<color=#e8d9bb>Following a major triumph on the main front, the royal forces spread out and pushed back, aiming to reclaim cities overrun by Eclipsites.</color>",
  ui_story_5076_50760701_2_dialog_content = "<color=#e8d9bb>Among them, some have completely been reduced to a \"nest\" of the Eclipsites.</color>",
  ui_story_5076_50760701_3_dialog_content = "<color=#e8d9bb>At that time, the \"heroes\" with new facades will step onto the stage.</color>",
  ui_story_5076_50760701_4_dialog_content = "Report! Sentries have confirmed the condition within the city—it's completely fallen, with Eclipsites running amok!",
  ui_story_5076_50760701_5_dialog_content = "And the people? Are there any signs of their survival?",
  ui_story_5076_50760701_6_dialog_content = "... None have survived.",
  ui_story_5076_50760701_7_dialog_content = "Stop the offensive. Your soldiers have no way of fighting their way into the city.",
  ui_story_5076_50760701_8_dialog_content = "The Eclipsites know no fear. Unless we bring the city down on their heads, they won't retreat.",
  ui_story_5076_50760701_9_dialog_content = "General... No, Captain, what should we do now?",
  ui_story_5076_50760701_10_dialog_content = "One of my squadmates is already on the way. Put the rest of your forces on standby at the rear.",
  ui_story_5076_50760701_11_dialog_content = "You mean... Ah!",
  ui_story_5076_50760701_12_dialog_content = "You there, soldier. You're in my way, so please take a step to the right.",
  ui_story_5076_50760701_13_dialog_content = "<color=#e8d9bb>Following the orders of the unfamiliar commander, the soldier shifts slightly to the side, and a flash of lightning erupts from her fingertips, demolishing the city gate that had resisted their prolonged attack.</color>",
  ui_story_5076_50760701_14_dialog_content = "The gates may be open, but there are still plenty of crafty Eclipsites hiding behind the city walls. I'll leave them to you... Cynthia.",
  ui_story_5076_50760701_15_dialog_content = "<color=#e8d9bb>With the longbow taut as a crescent moon, the hero in a verdant hue elegantly releases a shower of arrows. Each time when she plucks the bowstring, the Eclipsites skilled in ranged attacks fall one after another.</color>",
  ui_story_5076_50760701_16_dialog_content = "Good shooting! You must've really agitated them with that last attack, because they're starting to pour out of the gate.",
  ui_story_5076_50760701_17_dialog_content = "With me, knights! We're charging into battle!",
  ui_story_5076_50760701_18_dialog_content = "The knights don't stand a chance against those giant Eclipsites, Freya.",
  ui_story_5076_50760701_19_dialog_content = "They'll be fine! Friegson—The first wave is all yours!",
  ui_story_5076_50760701_20_dialog_content = "<color=#e8d9bb>With her resonant words, a blaze ignites in the distance. Roaring flames mercilessly engulf those burly monsters.</color>",
  ui_story_5076_50760701_21_dialog_content = "<color=#e8d9bb>A city that would take ordinary forces days to break is easily conquered by them.</color>",
  ui_story_5076_50760701_22_dialog_content = "<color=#e8d9bb>The cavalry led by the Silent Saintess Freya effortlessly tramples over the Eclipsites, her lance sweeping through with unmatched dominance. The fallen Eclipsites are quickly entwined in tongues of fire, writhing in agony.</color>",
  ui_story_5076_50760701_23_dialog_content = "How cruel... There's no need to toy with them like this, Friegson.",
  ui_story_5076_50760701_24_dialog_content = "Eclipsites deserve no sympathy.",
  ui_story_5076_50760701_25_dialog_content = "Where's the Vice Captain?",
  ui_story_5076_50760701_26_dialog_content = "The Eclipsites are retreating into the city. It seems they can feel some sort of fear after all... But I'm sure he's already waiting for them in there.",
  ui_story_5076_50760701_27_dialog_content = "If they don't escape, at least they'll be given a kind death... That's more than they deserve.",
  ui_story_5076_50760701_28_dialog_content = "<color=#e8d9bb>... As the Eclipsites, driven by instinctive fear, flee towards the rear gate, there is one figure standing alone to block their path.</color>",
  ui_story_5076_50760701_29_dialog_content = "<color=#e8d9bb>Merciless water magic, coupled with that frigid colossal sword, effortlessly crushes those who dared to advance, leaving the Eclipsites with no means of escape.</color>",
  ui_story_5076_50760701_30_dialog_content = "Death to all enemies... Death to all enemies... Death to all enemies...",
  ui_story_5076_50760701_31_dialog_content = "Eclipsites! <size=45>Die!!!</size>",
  ui_story_5076_50760702_1_dialog_content = "Eclipsites—Die—",
  ui_story_5076_50760702_2_dialog_content = "All of you must die!",
  ui_story_5076_50760702_3_dialog_content = "Calm down, Adras... You're scaring the soldiers.",
  ui_story_5076_50760702_4_dialog_content = "M-Marcela? Stay back, it's dangerous here!",
  ui_story_5076_50760702_5_dialog_content = "Is that... the Silent Hunter?",
  ui_story_5076_50760702_6_dialog_content = "So terrifying. Hard to imagine he's a legendary hero. Look at him! He's utterly...",
  ui_story_5076_50760702_7_dialog_content = "Keep it down; he might hear us.",
  ui_story_5076_50760702_8_dialog_content = "Is the battle over? Is everyone safe now?",
  ui_story_5076_50760702_9_dialog_content = "You did well, Adras.",
  ui_story_5076_50760702_10_dialog_content = "But... There wasn't a single survivor left in this city... Those rotten Eclipsites.",
  ui_story_5076_50760702_11_dialog_content = "That's not your fault. The rest of the team is coming, now let's go.",
  ui_story_5076_50760702_12_dialog_content = "...",
  ui_story_5076_50760702_13_dialog_content = "Another bonfire celebration for the Silent Hunters!",
  ui_story_5076_50760702_14_dialog_content = "Is that so? I don't recall being part of the team, or Anthony for that matter.",
  ui_story_5076_50760702_15_dialog_content = "You should go back, Anthony. Keep hanging around us, and people will start to fear you as well.",
  ui_story_5076_50760702_16_dialog_content = "Sorry, General Achilles, you're a hero but...",
  ui_story_5076_50760702_17_dialog_content = "I'm not a general anymore, Anthony. You don't need to refer to me like one.",
  ui_story_5076_50760702_18_dialog_content = "But...",
  ui_story_5076_50760702_19_dialog_content = "There are no generals or commanders here. Only the Silent Hunters.",
  ui_story_5076_50760702_20_dialog_content = "Don't beat around the bush, Anthony. If you want to eat with us, just say so.",
  ui_story_5076_50760702_21_dialog_content = "I see...",
  ui_story_5076_50760702_22_dialog_content = "Hey Ludweiss, don't eat all the cooked meat for yourself!",
  ui_story_5076_50760702_23_dialog_content = "What's the big deal? Just ask Friegson to make some more for you.",
  ui_story_5076_50760702_24_dialog_content = "She'd just burn it all to ash, you moron. Besides, I don't want anything she cooks.",
  ui_story_5076_50760702_25_dialog_content = "You got something to say to me?",
  ui_story_5076_50760702_26_dialog_content = "What she means is that she doesn't want to eat anything cooked by your Eclipsite-killing fire.",
  ui_story_5076_50760702_27_dialog_content = "That's right!",
  ui_story_5076_50760702_28_dialog_content = "I'm going somewhere else to eat.",
  ui_story_5076_50760702_29_dialog_content = "No, wait! I was only joking... Ugh, this is all your fault, Cynthia.",
  ui_story_5076_50760702_30_dialog_content = "I was just helping you speak your mind.",
  ui_story_5076_50760702_31_dialog_content = "We shouldn't fight while we're eating—Here, have some more.",
  ui_story_5076_50760702_32_dialog_content = "Wow, I'm so touched! You're the whole reason I chose to join the Silent Hunters.",
  ui_story_5076_50760702_33_dialog_content = "I thought you said it was to protect the kingdom and its people...",
  ui_story_5076_50760702_34_dialog_content = "\"The Silent Saintess,\" huh... I can't think of a less-fitting name for someone like you.",
  ui_story_5076_50760702_35_dialog_content = "Ah, I'm stuffed! I should probably get started with today's task now...",
  ui_story_5076_50760702_36_dialog_content = "What, are you still writing that journal of yours?",
  ui_story_5076_50760702_37_dialog_content = "The day I left my home, I decided to record everything about my travels. I'm not giving up on something like that so easily.",
  ui_story_5076_50760702_38_dialog_content = "But ever since Adras rescued me from the Eclipsites, I haven't traveled outside the kingdom.",
  ui_story_5076_50760702_39_dialog_content = "There were still plenty of places I wanted to see, but I ran into Eclipsites the moment I started traveling again. That's when you saved me, Freya—",
  ui_story_5076_50760702_40_dialog_content = "And after being stuck here for so long, my notes are now about you and your squadmates.",
  ui_story_5076_50760702_41_dialog_content = "Did you make sure to write about how heroic I was today?",
  ui_story_5076_50760702_42_dialog_content = "I was just about to do that, so could you give me some space? You're gonna spill my ink everywhere—",
  ui_story_5076_50760702_43_dialog_content = "I'm surprised you can still be so cheery after seeing the carnage out there today.",
  ui_story_5076_50760702_44_dialog_content = "Well, considering you were the one behind most of the carnage...",
  ui_story_5076_50760702_45_dialog_content = "That's enough, Freya. I'm also to blame for today's battle.",
  ui_story_5076_50760702_46_dialog_content = "She does bring up a good point though, Friegson.",
  ui_story_5076_50760702_47_dialog_content = "You shouldn't wind yourself up so tight in battle. Even the strongest bowstring will snap under enough pressure.",
  ui_story_5076_50760702_48_dialog_content = "Friegson has been at my side for a long time now... Before I was stationed in the north, we both served as palace guards.",
  ui_story_5076_50760702_49_dialog_content = "Compared to the rest of you, who are used to seeing battles like this, she still has some adjusting to do.",
  ui_story_5076_50760702_50_dialog_content = "As a noble from birth, I'm sure you've always seen the battlefield as a place of honor and glory, Freya. But you have to understand that in order to take life, you must be ready to lay down your own.",
  ui_story_5076_50760702_51_dialog_content = "The same goes for you, Friegson. We're all part of the Silent Hunters now, so treat them as you treated your comrades in the past.",
  ui_story_5076_50760702_52_dialog_content = "Forgive me, Captain...",
  ui_story_5076_50760702_53_dialog_content = "Correct me if I'm wrong, captain, but weren't you a part of the Elder Council before? That would make you an even greater noble than any of us.",
  ui_story_5076_50760702_54_dialog_content = "General Achilles grew up with the King back in the day.",
  ui_story_5076_50760702_55_dialog_content = "That would explain how someone so young became captain of the palace guards...",
  ui_story_5076_50760702_56_dialog_content = "But in the end, you chose to become a \"super soldier,\" just like us.",
  ui_story_5076_50760702_57_dialog_content = "I'd rather face the enemy in battle than take part in their political games.",
  ui_story_5076_50760702_58_dialog_content = "But, even if it's not your intention, the King is currently focused on suppressing the Elder Council. I doubt he'll trust you like he used to.",
  ui_story_5076_50760702_59_dialog_content = "Otherwise, he wouldn't let you become...",
  ui_story_5076_50760702_60_dialog_content = "That's enough of that! You were a palace guard too, right Cynthia? I hardly ever hear you talk about yourself, and Captain Achilles won't tell us anything either.",
  ui_story_5076_50760702_61_dialog_content = "I heard you approached the captain and volunteered for the project, whereas he chose the rest of us.",
  ui_story_5076_50760702_62_dialog_content = "I... I grew up in the woods, so there's not much to say.",
  ui_story_5076_50760702_63_dialog_content = "If my bow is needed on the front lines, then that's where I'll go.",
  ui_story_5076_50760702_64_dialog_content = "If they need me for the project, then I'll let them augment me however they see fit.",
  ui_story_5076_50760702_65_dialog_content = "\"Augment\"?",
  ui_story_5076_50760702_66_dialog_content = "Ah! I-It's nothing, Adras... Hey, aren't you going to eat?",
  ui_story_5076_50760702_67_dialog_content = "I was just about to...",
  ui_story_5076_50760702_68_dialog_content = "It's all because of that, huh? Neither people nor monsters, and we were forced to eat in a corner all by ourselves.",
  ui_story_5076_50760702_69_dialog_content = "We have a special mission. Our duty is to fight against even more powerful Eclipsites.",
  ui_story_5076_50760702_70_dialog_content = "Taking that first step into hell... It's best if we can keep other people away from this sort of thing.",
  ui_story_5076_50760702_71_dialog_content = "Even if we have to pay the price, it's better than letting them sacrifice their own lives.",
  ui_story_5076_50760702_72_dialog_content = "But Vice Captain... You gave up your status as a commander to join the Silent Hunters, just like the captain gave up his status as a general...",
  ui_story_5076_50760702_73_dialog_content = "After paying that price and constantly putting your life on the line, just for people to fear you... Don't you think that's unfair?",
  ui_story_5076_50760702_74_dialog_content = "The Silent Hunters are monsters created to fight powerful Eclipsites. Our purpose is to ensure their destruction; nothing else matters to us anymore.",
  ui_story_5076_50760702_75_dialog_content = "Only by remaining neutral and showing restraint can we continue our fight against the darkness.",
  ui_story_5076_50760702_76_dialog_content = "Do you feel like you've been wronged, Freya?",
  ui_story_5076_50760702_77_dialog_content = "Maybe just a little... But it doesn't matter!",
  ui_story_5076_50760702_78_dialog_content = "I'm the one who made the decision to protect others. I don't care what anyone else thinks, as long as I'm able to stick to my decision.",
  ui_story_5076_50760702_79_dialog_content = "I'm sure that applies to every one of us.",
  ui_story_5076_50760702_80_dialog_content = "How do you feel about the changes to your body, Vice Captain? Do the stares bother you when you're fighting?",
  ui_story_5076_50760702_81_dialog_content = "... Am I allowed to ask that sort of question, Captain?",
  ui_story_5076_50760702_82_dialog_content = "You already did.",
  ui_story_5076_50760702_83_dialog_content = "Like Captain Achilles once said, fighting those monsters will corrupt us over time. I was fully prepared to accept the consequences.",
  ui_story_5076_50760702_84_dialog_content = "As long as no one else has to suffer like this, I'm at peace with those consequences.",
  ui_story_5076_50760702_85_dialog_content = "How... How do you do it?",
  ui_story_5076_50760702_86_dialog_content = "You're like a completely different person off the battlefield! Please show me how you do that!",
  ui_story_5076_50760702_87_dialog_content = "Me too! Teach us how to suppress our emotions like you!",
  ui_story_5076_50760702_88_dialog_content = "I suppose...",
  ui_story_5076_50760702_89_dialog_content = "It all starts... With love.",
  ui_story_5076_50760702_90_dialog_content = "Hah?",
  ui_story_5076_50760702_91_dialog_content = "According to Ludweiss, my love and longing for my wife are sealed in this blade.",
  ui_story_5076_50760702_92_dialog_content = "So long as I hold it in my hands, our hearts will always be connected, no matter the distance.",
  ui_story_5076_50760702_93_dialog_content = "To protect her, and to keep this evil from reaching our happy home... That's all I care about.",
  ui_story_5076_50760702_94_dialog_content = "Suddenly I feel... really cold.",
  ui_story_5076_50760702_95_dialog_content = "Whenever the Vice Captain talks about his wife, all of my muscles start to feel sore...",
  ui_story_5076_50760702_96_dialog_content = "I still remember her...",
  ui_story_5076_50760702_97_dialog_content = "She stayed behind to help rebuild their city.",
  ui_story_5076_50760702_98_dialog_content = "No wonder the Vice Captain refuses to see anyone when he's not on a mission—",
  ui_story_5076_50760702_99_dialog_content = "... Are you friends with his wife as well, Ludweiss?",
  ui_story_5076_50760702_100_dialog_content = "Y-Yes! This reminds me that I promised to bring her some new teaching materials the next time I return.",
  ui_story_5076_50760702_101_dialog_content = "So why do you keep tagging along with us?",
  ui_story_5076_50760702_102_dialog_content = "Er—To make more records, of course!",
  ui_story_5076_50760702_103_dialog_content = "I guess there's no shortage of strange people on the battlefield these days.",
  ui_story_5076_50760702_104_dialog_content = "Enough about that. Here, have a cup of this wine. Adras made it himself—It was our personal favorite back in our military days!",
  ui_story_5076_50760702_105_dialog_content = "Cheers, everyone!",
  ui_story_5076_50760800_1_dialog_content = "Greetings, Adras! Where are you heading?",
  ui_story_5076_50760800_2_dialog_content = "My wife and I are showing the kids some locations for the new orphanage.",
  ui_story_5076_50760800_3_dialog_content = "Your wife? I didn't know about your... Anyway, congratulations on your new marriage!",
  ui_story_5076_50760800_4_dialog_content = "Huh? Marcela and I have been married for a long time now, but thanks all the same. Let's go, my dear.",
  ui_story_5076_50760800_5_dialog_content = "No... I don't want to go anywhere near the temple...",
  ui_story_5076_50760800_6_dialog_content = "Not there either? Then let's pick another place.",
  ui_story_5076_50760800_7_dialog_content = "Ohh... I'm truly sorry, Adras! It's... my oversight. You're so towering; I didn't see Lady Marcela at first glance.",
  ui_story_5076_50760800_8_dialog_content = "... Please take care on your way.",
  ui_story_5076_50760800_9_dialog_content = "Thank you.",
  ui_story_5076_50760800_10_dialog_content = "Have you been losing weight again, Marcela? People can hardly see you standing behind me; they might start thinking you're someone else.",
  ui_story_5076_50760800_11_dialog_content = "Hmph... Did you ever think that you're the one gaining weight?",
  ui_story_5076_50760800_12_dialog_content = "The reconstruction seems to be going well, Adras. You've been working hard, haven't you?",
  ui_story_5076_50760800_13_dialog_content = "Ludweiss! Long time no see, my friend!",
  ui_story_5076_50760800_14_dialog_content = "I'm happy to see that you've been doing so well lately.",
  ui_story_5076_50760800_15_dialog_content = "Is, uh... Is Marcela doing well too?",
  ui_story_5076_50760800_16_dialog_content = "You're talking to me as if she isn't right in front of you! Hmm? Where are you looking, Ludweiss? Don't you see Marcela standing behind me?",
  ui_story_5076_50760800_17_dialog_content = "... Has Adras been listening to you like a good husband, Marcela?",
  ui_story_5076_50760800_18_dialog_content = "Don't tease him too much, Ludweiss. It's not easy for him to break away from the front lines, and he only just returned.",
  ui_story_5076_50760800_19_dialog_content = "That reminds me... Weren't you going somewhere with Freya and the others? Sorry, maybe it's because I've been so busy, but I can't seem to remember.",
  ui_story_5076_50760800_20_dialog_content = "It's perfectly understandable! After all, you're overseeing the reconstruction of an entire city. I just came to deliver a letter from Achilles.",
  ui_story_5076_50760800_21_dialog_content = "A letter?",
  ui_story_5076_50760800_22_dialog_content = "Adras, Marcela, hello!",
  ui_story_5076_50760800_23_dialog_content = "Hi there, Adras!",
  ui_story_5076_50760800_24_dialog_content = "Dummy, why only greet Adras? Didn't I teach you—",
  ui_story_5076_50760800_25_dialog_content = "Now, now, don't pick on your little brother.",
  ui_story_5076_50760800_26_dialog_content = "You don't mind, do you, Marcela?",
  ui_story_5076_50760800_27_dialog_content = "Mmm.",
  ui_story_5076_50760800_28_dialog_content = "Sorry, Adras, and... Mar-Marcela.",
  ui_story_5076_50760800_29_dialog_content = "Adras, back from the outskirts today?",
  ui_story_5076_50760800_30_dialog_content = "Adras, these grapes are from our own vineyard. Take them; they taste great and are great for making wine.",
  ui_story_5076_50760800_31_dialog_content = "Fellas, make way! Adras, check out this fabric; it's just right for making new clothes for Marcela.",
  ui_story_5076_50760800_32_dialog_content = "You really don't need to do this. Marcela won't let me hear the end of it if you do.",
  ui_story_5076_50760800_33_dialog_content = "Ah—Marcela?",
  ui_story_5076_50760800_34_dialog_content = "Where did you go, my love?",
  ui_story_5076_50760800_35_dialog_content = "...I saw her running back!",
  ui_story_5076_50760800_36_dialog_content = "Yeah, she must be shy, haha!",
  ui_story_5076_50760800_37_dialog_content = "Or maybe she's mad, it's all your fault.",
  ui_story_5076_50760800_38_dialog_content = "Let's go; leave some private space for our mighty hero, alright?",
  ui_story_5076_50760800_39_dialog_content = "Sorry Ludweiss, the people here can be a bit much at times. What were you saying about—",
  ui_story_5076_50760800_40_dialog_content = "Ludweiss? Wh-Why are you crying...? Are you alright?",
  ui_story_5076_50760800_41_dialog_content = "I... I... I'm fine, it's just... That was really touching just now.",
  ui_story_5076_50760800_42_dialog_content = "Everyone treats you both so well... I'm so happy for you.",
  ui_story_5076_50760800_43_dialog_content = "That's because they're all good people.",
  ui_story_5076_50760800_44_dialog_content = "I know... They truly are good people...",
  ui_story_5076_50760800_45_dialog_content = "Here's a handkerchief. Take it.",
  ui_story_5076_50760800_46_dialog_content = "Feeling better now?",
  ui_story_5076_50760800_47_dialog_content = "Yes. Thank you, Adras—",
  ui_story_5076_50760800_48_dialog_content = "You mentioned something about a letter. Does the captain have new orders for me?",
  ui_story_5076_50760800_49_dialog_content = "... The king is preparing for a new expedition. He wants to destroy the evil at its source.",
  ui_story_5076_50760800_50_dialog_content = "This time, he's sending you and the Silent Hunters to deal with the abyss first discovered in the north.",
  ui_story_5076_50760800_51_dialog_content = "So, the world is still not at peace.",
  ui_story_5076_50760800_52_dialog_content = "I accept.",
  ui_story_5076_50760800_53_dialog_content = "Will any other forces be joining the Silent Hunters on this campaign?",
  ui_story_5076_50760800_54_dialog_content = "From what I know, two legions have also been assigned to it.",
  ui_story_5076_50760800_55_dialog_content = "Who will be leading them?",
  ui_story_5076_50760800_56_dialog_content = "It's High Priest Lucius... He's been reinstated by the king. Not only that, he will be assuming full command of the entire expedition.",
  ui_story_5076_50760800_57_dialog_content = "What? That traitorous scum?!",
  ui_story_5076_50760800_58_dialog_content = "But he mobilized his own private forces during the last war! Countless people died because of him!",
  ui_story_5076_50760800_59_dialog_content = "All of those cities where no one survived were the results of his crimes! You mean to tell me that this man is suddenly in charge of our operation?!",
  ui_story_5076_50760800_60_dialog_content = "It's his fault that so many innocent people died! Marcela nearly lost her life because of him, as well!",
  ui_story_5076_50760800_61_dialog_content = "No! He deserves no mercy! I won't forgive him for—",
  ui_story_5076_50760800_62_dialog_content = "Please just calm down, Adras. These are the king's orders.",
  ui_story_5076_50760800_63_dialog_content = "Even so, I refuse to work for the likes of Lucius!",
  ui_story_5076_50760800_64_dialog_content = "Curse him—",
  ui_story_5076_50760800_65_dialog_content = "Don't take your frustration out on Ludweiss, Adras.",
  ui_story_5076_50760800_66_dialog_content = "Marcela? You're back...",
  ui_story_5076_50760800_67_dialog_content = "The king may be surrounded by liars and flatterers now... But they're not the ones you've been protecting, are they?",
  ui_story_5076_50760800_68_dialog_content = "Or do you wish to see our city destroyed for a second time?",
  ui_story_5076_50760800_69_dialog_content = "For the king to swallow his pride and let Lucius take credit for this campaign will only further his evil goals.",
  ui_story_5076_50760800_70_dialog_content = "But as much as it pains me, I have no way of refusing him.",
  ui_story_5076_50760800_71_dialog_content = "The captain needs me, my allies need me... And the innocent people of our kingdom need me...",
  ui_story_5076_50760800_72_dialog_content = "... I accept my orders, Ludweiss.",
  ui_story_5076_50760800_73_dialog_content = "Once the children and I decide on a new location for the orphanage, I'll gather my equipment and depart right away.",
  ui_story_5076_50760800_74_dialog_content = "Understood... Thank you, Adras.",
  ui_story_5076_50760800_75_dialog_content = "Thank you... For continuing to fight for this world.",
  ui_story_5076_50760800_76_dialog_content = "What about you? What's your next course of action?",
  ui_story_5076_50760800_77_dialog_content = "Me...? Well, I kind of want to see the aurora for myself—",
  ui_story_5076_50760800_78_dialog_content = "The expedition will be extremely dangerous. It's best if you don't come along this time.",
  ui_story_5076_50760800_79_dialog_content = "You should leave this place, Ludweiss.",
  ui_story_5076_50760800_80_dialog_content = "The world is a vast and incredible place. I'm sure you'll find someplace far more interesting to write about in your journal.",
  ui_story_5076_50760800_81_dialog_content = "... Sorry, but I can't leave just yet. I still have some matters to settle here.",
  ui_story_5076_50760800_82_dialog_content = "Besides, I wouldn't mind staying and keeping Marcela company. Right, Marcela?",
  ui_story_5076_50760800_83_dialog_content = "Then I'll leave her in your hands, Ludweiss.",
  ui_story_5076_50760800_84_dialog_content = "Just come back as soon as you can. There's no telling when I might change my mind, you know!",
  ui_story_5076_50760800_85_dialog_content = "Then I'll make you the same promise I made her—",
  ui_story_5076_50760800_86_dialog_content = "That I'll come back no matter what happens.",
  ui_story_5076_50760800_87_dialog_content = "And if I happen to come across the aurora during my travels—",
  ui_story_5076_50760800_88_dialog_content = "I'll be sure to tell you all about its beauty, my friend.",
  ui_story_5076_50760800_89_dialog_content = "Sounds like a deal... I can't wait to hear your story, o mighty hero.",
  ui_story_5076_50760900_1_dialog_content = "\"Time always seems to slip by when we least notice it... And before long—\"",
  ui_story_5076_50760900_2_dialog_content = "Teacher Ludweiss, come out here fast!",
  ui_story_5076_50760900_3_dialog_content = "What's with all the commotion? I hardly get a chance to write in my journal these days, you know...",
  ui_story_5076_50760900_4_dialog_content = "Long time no see, Ludweiss.",
  ui_story_5076_50760900_5_dialog_content = "Adras? You...",
  ui_story_5076_50760900_6_dialog_content = "Heh... Welcome home, Adras.",
  ui_story_5076_50760900_7_dialog_content = "Hurry up and shut the door, kids! If anyone sees that our mighty hero is back, the whole town will trample this place into dust!",
  ui_story_5076_50760900_8_dialog_content = "The children tell me that you've been managing the orphanage for some time. I can't thank you enough for your help, my friend.",
  ui_story_5076_50760900_9_dialog_content = "I never thought raising a bunch of kids could be so difficult. How on earth did Marcela—Cough, cough, cough!",
  ui_story_5076_50760900_10_dialog_content = "That reminds me, where is she? The children said I might find her here with you.",
  ui_story_5076_50760900_11_dialog_content = "Huh? With me?",
  ui_story_5076_50760900_12_dialog_content = "Ah! Sh-She saw me writing in my journal, so she left just now.",
  ui_story_5076_50760900_13_dialog_content = "I'm so sorry, I know you must be dying to see her...",
  ui_story_5076_50760900_14_dialog_content = "It's fine, Ludweiss. As long as I hold this sword in my hands, she's never far from my side.",
  ui_story_5076_50760900_15_dialog_content = "The northern expedition was long, but not nearly long enough to separate our hearts.",
  ui_story_5076_50760900_16_dialog_content = "Still, it feels a bit unsettling not to hear her voice after such a long journey... Do you know when she'll be back?",
  ui_story_5076_50760900_17_dialog_content = "I'm not sure—That reminds me, we caught wind of your victorious return a few days ago! I hear the king commended you all for your success.",
  ui_story_5076_50760900_18_dialog_content = "That's right. We were all given new titles, as well.",
  ui_story_5076_50760900_19_dialog_content = "I remember reading about that in Freya's letter too!",
  ui_story_5076_50760900_20_dialog_content = "Your title is \"Regal\" now, right? And Freya is \"Requiem,\" Friegson is \"Frostfire,\" and Cynthia is \"Mythos.\"",
  ui_story_5076_50760900_21_dialog_content = "She forgot to tell me Achilles' title, though.",
  ui_story_5076_50760900_22_dialog_content = "\"Claymore.\" That's Captain Achilles' new title.",
  ui_story_5076_50760900_23_dialog_content = "Sounds imposing... Freya said they gave her a crown of laurels too. Where's yours?",
  ui_story_5076_50760900_24_dialog_content = "I turned it down.",
  ui_story_5076_50760900_25_dialog_content = "Huh? Why?",
  ui_story_5076_50760900_26_dialog_content = "The laurel crown I wear into battle was given to me many years ago, when I ended the war against the rebels. Back then, I was rewarded with both love and honor.",
  ui_story_5076_50760900_27_dialog_content = "That's why... I don't need another one.",
  ui_story_5076_50760900_28_dialog_content = "Ah, that's a shame. I would've loved to see everyone being rewarded for their efforts.",
  ui_story_5076_50760900_29_dialog_content = "Even though I turned down another crown, I still asked the king for a reward in the form of land and money.",
  ui_story_5076_50760900_30_dialog_content = "How practical of you!",
  ui_story_5076_50760900_31_dialog_content = "It's for my townspeople—They lost so much because of the war. I know it will never be enough to replace what was lost, but...",
  ui_story_5076_50760900_32_dialog_content = "I just hope it will make their lives a little easier.",
  ui_story_5076_50760900_33_dialog_content = "Adras...",
  ui_story_5076_50760900_34_dialog_content = "I saw the aurora while I was in the north, Ludweiss.",
  ui_story_5076_50760900_35_dialog_content = "To be honest, I saw the aurora many times during my time in the north, but I never saw it as anything special. I don't know why, but it felt different during this last expedition for some reason.",
  ui_story_5076_50760900_36_dialog_content = "When I saw the aurora rip through the darkness and illuminate the sky, all I could think about was wishing that Marcela was there to see it.",
  ui_story_5076_50760900_37_dialog_content = "If there wasn't so much hidden danger in the world, maybe everyone could see something as beautiful as that.",
  ui_story_5076_50760900_38_dialog_content = "For that reason, I don't want to tell you more about it... I want you to see it for yourself someday, Ludweiss.",
  ui_story_5076_50760900_39_dialog_content = "It feels like you've changed, Adras... But... Never mind. Since you're in such high spirits, that must mean the campaign went really well, right?",
  ui_story_5076_50760900_40_dialog_content = "That's right. We managed to destroy the abyss, but at a cost. Fortunately, it doesn't seem like any normal soldiers were lost.",
  ui_story_5076_50760900_41_dialog_content = "We even saw a spectacular meteor shower before we left.",
  ui_story_5076_50760900_42_dialog_content = "Freya was moved beyond words. Cynthia and the others seemed to enjoy it as well.",
  ui_story_5076_50760900_43_dialog_content = "Soon afterward, the captain made these Star Crests for us.",
  ui_story_5076_50760900_44_dialog_content = "These are so well-made! I had no idea Achilles had a knack for this sort of thing.",
  ui_story_5076_50760900_45_dialog_content = "No matter where we go, we will always be the Silent Hunters who beheld the stars that day.",
  ui_story_5076_50760900_46_dialog_content = "A memory like this is far more precious than any laurel crown.",
  ui_story_5076_50760900_47_dialog_content = "It almost sounds like you're saying goodbye...",
  ui_story_5076_50760900_48_dialog_content = "That's because I am. I've decided to retire from service and spend the rest of my days here, in peace and with Marcela at my side.",
  ui_story_5076_50760900_49_dialog_content = "Freya didn't mention anything about that in her letter. What will happen to the Silent Hunters?",
  ui_story_5076_50760900_50_dialog_content = "We... Haven't disbanded yet. But as direct subordinates to the crown, we will eventually be subjected to Lucius' control.",
  ui_story_5076_50760900_51_dialog_content = "I refuse to obey him. The same goes for the rest of the Silent Hunters.",
  ui_story_5076_50760900_52_dialog_content = "Besides, with the threat of the Eclipsites gone, the kingdom has no need of us anymore. That might have been the reason why none of them tried to stop me from leaving.",
  ui_story_5076_50760900_53_dialog_content = "I couldn't agree more. You must be tired after so many years of fighting, Adras; if anyone deserves to rest, it's you.",
  ui_story_5076_50760900_54_dialog_content = "Heheh, I can't put my feet up just yet. I still need to find Marcela and surprise her.",
  ui_story_5076_50760900_55_dialog_content = "It's getting late. I'm sure she'll be back soon, so don't go running off on your own.",
  ui_story_5076_50760900_56_dialog_content = "Was he being serious? He didn't see Marcela here, so where else could she be? Hmm...",
  ui_story_5076_50760900_57_dialog_content = "Could it be that his heart is finally starting to heal? That's a good thing... Right?",
  ui_story_5076_50760900_58_dialog_content = "<color=#e8d9bb>The hero returns after the triumph, and the city celebrates him with a grand ceremony.</color>",
  ui_story_5076_50760900_59_dialog_content = "<color=#e8d9bb>The <color=#FFB400>Temple</color>, the place of love for the hero, is specially renovated and solemnly presented to him.</color>",
  ui_story_5076_50760900_60_dialog_content = "<color=#e8d9bb>No one anticipated that it would soon witness a time of great turmoil.</color>",
  ui_story_5076_50760900_61_dialog_content = "How did this happen? The Temple we put much effort into renovating...",
  ui_story_5076_50760900_62_dialog_content = "What in the world happened here?",
  ui_story_5076_50760900_63_dialog_content = "Adras? You...",
  ui_story_5076_50760900_64_dialog_content = "Why is the temple in ruins?",
  ui_story_5076_50760900_65_dialog_content = "Maybe... it's the Eclipsites?",
  ui_story_5076_50760900_66_dialog_content = "Blasted Eclipsites—How dare they set foot in this place, especially when it means so much to Marcela and me!!!",
  ui_story_5076_50760900_67_dialog_content = "Please don't be mad. At least nobody's hurt right now. Take it easy.",
  ui_story_5076_50760900_68_dialog_content = "... I'm relieved to hear that no one was hurt. Leave the temple's repairs to me.",
  ui_story_5076_50760900_69_dialog_content = "We'll help too.",
  ui_story_5076_50760900_70_dialog_content = "Very well, but stay alert. There may still be Eclipsites lurking in the area.",
  ui_story_5076_50760900_71_dialog_content = "You gotta be careful too!",
  ui_story_5076_50760900_72_dialog_content = "I'll bring my sword and keep watch over this place when night falls. We can't allow another tragedy to happen to this place, and I won't let the Eclipsites have their way again...",
  ui_story_5076_50760900_73_dialog_content = "<color=#e8d9bb>Thanks to the joint effort of the hero and his hardworking helpers, the Temple was quickly repaired. However—</color>",
  ui_story_5076_50760900_74_dialog_content = "What is this?",
  ui_story_5076_50760900_75_dialog_content = "I never left town even once... What kind of Eclipsite is capable of avoiding my detection like this?",
  ui_story_5076_50760900_76_dialog_content = "It keeps infiltrating the city right under my nose... The townspeople are in danger...",
  ui_story_5076_50760900_77_dialog_content = "I wouldn't worry about it too much. Maybe the Eclipsite is just too weak to draw your attention. Here, I'll try sensing it.",
  ui_story_5076_50760900_78_dialog_content = "Huh? There's something strange about this wreckage...",
  ui_story_5076_50760900_79_dialog_content = "Hey Adras? You said that Marcela was too afraid of the temple to even approach it, didn't you?",
  ui_story_5076_50760900_80_dialog_content = "Yes, that seems to be the case. Whenever I come to the temple, she refuses to come along.",
  ui_story_5076_50760900_81_dialog_content = "So that's the reason...",
  ui_story_5076_50760900_82_dialog_content = "Teacher Ludweiss, look!",
  ui_story_5076_50760900_83_dialog_content = "This kinda looks like a mark left by a sword...",
  ui_story_5076_50760900_84_dialog_content = "Shh—!!!",
  ui_story_5076_50760900_85_dialog_content = "What is it?",
  ui_story_5076_50760900_86_dialog_content = "I-It's nothing! This boy just wants to help you rebuild the temple, but he's still too young.",
  ui_story_5076_50760900_87_dialog_content = "Thanks for the offer, little one, but you need to go back. This place isn't safe.",
  ui_story_5076_50760900_88_dialog_content = "Go on, hurry home!",
  ui_story_5076_50760900_89_dialog_content = "So did you manage to sense anything, Ludweiss?",
  ui_story_5076_50760900_90_dialog_content = "I did... But it's something very small, like a mischievous, little Eclipsite. I don't think it poses much of a threat.",
  ui_story_5076_50760900_91_dialog_content = "Even so, we can't afford to take any chances. It looks like I'll need your help defending the temple, Ludweiss.",
  ui_story_5076_50760900_92_dialog_content = "Me? Then... I'll start by taking tonight's shift. Don't worry, the militia will be on standby if anything happens. For now... Just go home and get some rest before Marcela starts to worry...",
  ui_story_5076_50760900_93_dialog_content = "Ugh, what a night... The temple floor isn't the softest place to sleep.",
  ui_story_5076_50760900_94_dialog_content = "Teacher Ludweiss, Brother Adras said he'd drop by tonight to keep watch. Oh, by the way, he's looking pretty cheerful.",
  ui_story_5076_50760900_95_dialog_content = "Sounds like he got plenty of rest, which means the temple shouldn't have been...",
  ui_story_5076_50760900_96_dialog_content = "Why... Why is he so stable all of a sudden? Could it be that... He saw Marcela again?",
  ui_story_5076_50760900_97_dialog_content = "Ludweiss, you must be tired after keeping watch all night. You can head back now.",
  ui_story_5076_50760900_98_dialog_content = "If I leave and Adras goes near the temple again...",
  ui_story_5076_50760900_99_dialog_content = "Don't worry, Ludweiss. We have faith in Adras.",
  ui_story_5076_50760900_100_dialog_content = "We can't have you staying here all the time. It's fine; we owe Adras too much, so we'll all work together with you...",
  ui_story_5076_50760900_101_dialog_content = "... I have an idea. If the temple ends up in shambles again tomorrow, I need everyone to play along with this—",
  ui_story_5076_50760900_102_dialog_content = "As expected, the temple was damaged again.",
  ui_story_5076_50760900_103_dialog_content = "What in the world...",
  ui_story_5076_50760900_104_dialog_content = "... Have you been sleeping well at home, Adras?",
  ui_story_5076_50760900_105_dialog_content = "Of course. After all, Marcela is with me again... But why do you ask?",
  ui_story_5076_50760900_106_dialog_content = "Sigh... Looks like we're back to square one again...",
  ui_story_5076_50760900_107_dialog_content = "Still, I'm happy to see that your mind's at peace again.",
  ui_story_5076_50760900_108_dialog_content = "What are you talking about?",
  ui_story_5076_50760900_109_dialog_content = "As a Caelestite, I just... Feel a little helpless. After all, this is the first time I've wished for an <color=#FFB400>illness</color> to remain uncured...",
  ui_story_5076_50760900_110_dialog_content = "Adras, we caught that Eclipsite!",
  ui_story_5076_50760900_111_dialog_content = "Really? How did you do it?",
  ui_story_5076_50760900_112_dialog_content = "It was a small Eclipsite, agile and swift, only causing trouble in the early hours. But don't worry, it fell into our trap and got caught!",
  ui_story_5076_50760900_113_dialog_content = "We've already eliminated that Eclipsite. You can rest easy now.",
  ui_story_5076_50760900_114_dialog_content = "Yeah, Brother Adras, I saw that little Eclipsites get squashed with my own eyes.",
  ui_story_5076_50760900_115_dialog_content = "Ahem—",
  ui_story_5076_50760900_116_dialog_content = "Oh! By the way, we just passed by your place and heard Marcela might need you for something. You better hurry back.",
  ui_story_5076_50760900_117_dialog_content = "Understood. I'll be back to help with the repairs tomorrow.",
  ui_story_5076_50760900_118_dialog_content = "No, just leave it to us! You've done so much for us, and we don't wanna trouble you anymore. Go back and spend more time with Marcela.",
  ui_story_5076_50760900_119_dialog_content = "It'd be too embarrassing if we can't get such a small thing right.",
  ui_story_5076_50760900_120_dialog_content = "Just do as they say, Adras. After a few days—",
  ui_story_5076_50760900_121_dialog_content = "Teacher Ludweiss! Ahem!",
  ui_story_5076_50760900_122_dialog_content = "—Just continue keeping your distance! Everything's fine now, so just keep an eye on things from afar, okay?",
  ui_story_5076_50760900_123_dialog_content = "You're all acting so strangely.",
  ui_story_5076_50760900_124_dialog_content = "But if Marcela needs me right now... I should just go home...",
  ui_story_5076_50760900_125_dialog_content = "I'll leave the rest to you, Ludweiss.",
  ui_story_5076_50760900_126_dialog_content = "Huh? Er... Sure! Just... leave it all to me.",
  ui_story_5076_50761000_1_dialog_content = "They actually managed to rebuild this city.",
  ui_story_5076_50761000_2_dialog_content = "See? I told you Ludweiss wasn't exaggerating in her letter!",
  ui_story_5076_50761000_3_dialog_content = "The last time we gathered here, this city was hardly different from a pile of rubble.",
  ui_story_5076_50761000_4_dialog_content = "What could have possibly driven these people to make such a miracle happen?",
  ui_story_5076_50761000_5_dialog_content = "I'm sure it was their faith in their hero.",
  ui_story_5076_50761000_6_dialog_content = "They're looking at us again... Hide my face, Freya.",
  ui_story_5076_50761000_7_dialog_content = "Hey! Over here!",
  ui_story_5076_50761000_8_dialog_content = "Miss Ludweiss, who are they? Would you please introduce them?",
  ui_story_5076_50761000_9_dialog_content = "These are Adras' friends, the kingdom's legendary Star Warriors! They've come to visit him.",
  ui_story_5076_50761000_10_dialog_content = "Wow, we're so honored to have them here! Adras and Marcela will be overjoyed for sure.",
  ui_story_5076_50761000_11_dialog_content = "Marcela? But Captain, didn't you say she... I see. You've all been caring for the Vice Captain, right?",
  ui_story_5076_50761000_12_dialog_content = "Thank you.",
  ui_story_5076_50761000_13_dialog_content = "Hehe, esteemed guests, would you like to try our local specialties?",
  ui_story_5076_50761000_14_dialog_content = "Could you please take some to Adras as well? He's... well, he and Marcela could use some care too.",
  ui_story_5076_50761000_15_dialog_content = "Everyone...",
  ui_story_5076_50761000_16_dialog_content = "Hehe, please say hello to him and \"Marcela\" for us.",
  ui_story_5076_50761000_17_dialog_content = "It's good to see you all again. I wanted to welcome you personally, but Marcela volunteered to do it instead.",
  ui_story_5076_50761000_18_dialog_content = "After all, she and Ludweiss are already in the city. They both work in the orphanage now.",
  ui_story_5076_50761000_19_dialog_content = "Don't worry about it. Marcela showed us the fields just now. They're huge! You must be so busy preparing for the harvest, right?",
  ui_story_5076_50761000_20_dialog_content = "Yes, but it's also very peaceful... I couldn't ask for a better life.",
  ui_story_5076_50761000_21_dialog_content = "That's good to hear... Adras.",
  ui_story_5076_50761000_22_dialog_content = "How have you all been?",
  ui_story_5076_50761000_23_dialog_content = "Fine, I suppose. I went back to serving as a palace guard, so I could keep defending the kingdom.",
  ui_story_5076_50761000_24_dialog_content = "Since we're not needed anymore, I've been wandering throughout the kingdom... The cold stares never stop, but I've been doing well.",
  ui_story_5076_50761000_25_dialog_content = "The forest is a lot more peaceful, Friegson. Why not join me instead?",
  ui_story_5076_50761000_26_dialog_content = "... I don't want my flames to destroy your paradise.",
  ui_story_5076_50761000_27_dialog_content = "You could always stay here, Friegson. The people in this city are kind, and they won't reject you because of your scars.",
  ui_story_5076_50761000_28_dialog_content = "Thank you for the offer, Vice Captain. I can tell that they're good people, but... It's better if I don't stay.",
  ui_story_5076_50761000_29_dialog_content = "A reunion like this is hard to come by, so why not stay a while longer and tell Adras about your lives? We can even build a bonfire, just like before.",
  ui_story_5076_50761000_30_dialog_content = "Marcela's right. We should have a bonfire tonight, just like old times. I'd love to sit and talk to everyone a little more, as well.",
  ui_story_5076_50761000_31_dialog_content = "... I don't see why not.",
  ui_story_5076_50761000_32_dialog_content = "Fine by me! It's been too long since I've had the Vice Captain's home cooking! I bet there are plenty of wine cellars around here, too—",
  ui_story_5076_50761000_33_dialog_content = "Come on Friegson, let's go grab a barrel of the good stuff!",
  ui_story_5076_50761000_34_dialog_content = "Would that be alright, Vice Captain?",
  ui_story_5076_50761000_35_dialog_content = "Of course. Marcela can show you where it is.",
  ui_story_5076_50761000_36_dialog_content = "But...",
  ui_story_5076_50761000_37_dialog_content = "The wine cellar is easy enough to find. The entrance is in the shed behind the house.",
  ui_story_5076_50761000_38_dialog_content = "Let's grab a few more barrels and make this a real party! Now quit slacking off and give us a hand, Cynthia!",
  ui_story_5076_50761000_39_dialog_content = "But I have to observe proper etiquette while...",
  ui_story_5076_50761000_40_dialog_content = "Oh, just get over it and help us out!",
  ui_story_5076_50761000_41_dialog_content = "Have you been well lately, Captain?",
  ui_story_5076_50761000_42_dialog_content = "Lucius' authority goes beyond that of his status as High Priest. He's powerful enough to stand against the Elder Council now... And my family wishes for me to stand at their side.",
  ui_story_5076_50761000_43_dialog_content = "But the Silent Hunters are not assassins. Now that the kingdom is safe from the Eclipsites, we have no reason to get involved in these matters.",
  ui_story_5076_50761000_44_dialog_content = "I just want to spend time with everyone, Adras. Just like this.",
  ui_story_5076_50761000_45_dialog_content = "... I understand. Hopefully you'll find some peace here, if only for a short time.",
  ui_story_5076_50761000_46_dialog_content = "Let's go prepare tonight's dinner, Marcela.",
  ui_story_5076_50761000_47_dialog_content = "Do you think he's happy, Ludweiss?",
  ui_story_5076_50761000_48_dialog_content = "As far as I can tell, he's definitely happy now...",
  ui_story_5076_50761000_49_dialog_content = "We've been carrying on with this lie, but if—",
  ui_story_5076_50761000_50_dialog_content = "Marcela once said that Adras is willing to fight for his people for the rest of his life.",
  ui_story_5076_50761000_51_dialog_content = "And the people here are doing everything they can to protect their hero's last bit of peace and happiness.",
  ui_story_5076_50761000_52_dialog_content = "It's not just a lie, Captain Achilles. At least not the way I see it.",
  ui_story_5076_50761000_53_dialog_content = "Those who hide from their pain will eventually awaken from even the most carefully-crafted dream. When that happens... Will he suffer even more? Or will he be happy with that fleeting sense of happiness?",
  ui_story_5076_50761000_54_dialog_content = "He's getting better.",
  ui_story_5076_50761000_55_dialog_content = "I don't sense the corruption spreading in him anymore. If anything, he's gotten even more energetic.",
  ui_story_5076_50761000_56_dialog_content = "So if he awakens from his dream someday... I'll be there to bear any resentment he might have.",
  ui_story_5076_50761000_57_dialog_content = "I'm their captain, Ludweiss. If that day ever comes, I'll be the one to bear responsibility for everything.",
  ui_story_5076_50761000_58_dialog_content = "This reminds me; I hear that the orphanage is fully capable of running itself now. Do you plan on returning to your travels soon?",
  ui_story_5076_50761000_59_dialog_content = "Well, I've always wanted to see the shooting stars up in the north!",
  ui_story_5076_50761000_60_dialog_content = "Shooting stars? Not the aurora?",
  ui_story_5076_50761000_61_dialog_content = "Then again, you're free to do as you wish. At the very least, you can escape your trappings... And see the world in our place.",
  ui_story_5076_50761000_62_dialog_content = "I will, and you'll be the first to read about everything I see out there.",
  ui_story_5076_50761000_63_dialog_content = "Chug, chug, chug! Come on, you can do it!",
  ui_story_5076_50761000_64_dialog_content = "Glug, glug, glug—",
  ui_story_5076_50761000_65_dialog_content = "I-I surrender... I can't drink anymore.",
  ui_story_5076_50761000_66_dialog_content = "Get up, Friegson! How could you lose to Cynthia again?!",
  ui_story_5076_50761000_67_dialog_content = "One captain... Two captains...",
  ui_story_5076_50761000_68_dialog_content = "Oh, she's really hammered now.",
  ui_story_5076_50761000_69_dialog_content = "Are you up next, Freya?",
  ui_story_5076_50761000_70_dialog_content = "A-Ahem, I'll have you know I'm a highly cultured noblewoman! How could I possibly indulge in this sort of behavior?",
  ui_story_5076_50761000_71_dialog_content = "... Coward.",
  ui_story_5076_50761000_72_dialog_content = "Would you mind helping Friegson to her room, Marcela?",
  ui_story_5076_50761000_73_dialog_content = "... I'm happy for you, Vice Captain.",
  ui_story_5076_50761000_74_dialog_content = "You're doing way better than any of us... No one treats you like a monster, or makes you do their dirty work.",
  ui_story_5076_50761000_75_dialog_content = "You're drunk, Friegson. You should go lie down.",
  ui_story_5076_50761000_76_dialog_content = "Why does everyone in the kingdom look at me that way? It's not like I wanted to end up like this!",
  ui_story_5076_50761000_77_dialog_content = "I didn't do anything wrong! I just wanted to protect them...",
  ui_story_5076_50761000_78_dialog_content = "Take her back to bed, Freya.",
  ui_story_5076_50761000_79_dialog_content = "But Captain... She's crying.",
  ui_story_5076_50761000_80_dialog_content = "She's exhausted. I think she needs to let this out.",
  ui_story_5076_50761000_81_dialog_content = "I didn't do anything! I'm a monster slayer, not a monster!",
  ui_story_5076_50761000_82_dialog_content = "I just wanted to help that old man find his way! Why did he curse at me as soon as he saw me?!",
  ui_story_5076_50761000_83_dialog_content = "He was clearly scared of me, but that didn't stop him! Why? Is it because he knew I wouldn't hurt him? Who's the one being unreasonable here—",
  ui_story_5076_50761000_84_dialog_content = "...",
  ui_story_5076_50761000_85_dialog_content = "Don't cry, Friegson. It really doesn't suit you at all.",
  ui_story_5076_50761000_86_dialog_content = "Vice Captain? I... I really am happy for you. At least you get to be a hero. But why does the kingdom see the rest of us as monsters...?",
  ui_story_5076_50761000_87_dialog_content = "Why, Vice Captain...? What should we do...?",
  ui_story_5076_50761000_88_dialog_content = "The love in my heart is nearly gone now... What should I do...?",
  ui_story_5076_50761000_89_dialog_content = "The people here can still see you for the hero you've always been... So why is everyone else so stupid?",
  ui_story_5076_50761000_90_dialog_content = "Friegson...",
  ui_story_5076_50761000_91_dialog_content = "Don't worry about her too much, Adras. She's been keeping these feelings to herself for too long, and she finally found someone to share them with.",
  ui_story_5076_50761000_92_dialog_content = "... Drink up, Vice Captain! Let's... Get drunk together...!",
  ui_story_5076_50761000_93_dialog_content = "Cheers, Friegson. This cup is for you.",
  ui_story_5076_50761000_94_dialog_content = "Come on, Cynthia! The Vice Captain looks like he needs a good challenge!",
  ui_story_5076_50761000_95_dialog_content = "You should know I'm extremely confident in myself.",
  ui_story_5076_50761000_96_dialog_content = "Well I'm not, so it looks like I'm bound to lose.",
  ui_story_5076_50761000_97_dialog_content = "Glug, glug, glug—",
  ui_story_5076_50761000_98_dialog_content = "Keep them coming! I'll show you the courage of the Northwind Legion!",
  ui_story_5076_50761000_99_dialog_content = "Marcela... Where are you... I can't catch up to you.",
  ui_story_5076_50761000_100_dialog_content = "A song? But we're not on the clock... Ah, I suppose one song wouldn't hurt.",
  ui_story_5076_50761000_101_dialog_content = "\"Take my hand—\"",
  ui_story_5076_50761000_102_dialog_content = "The Vice Captain must be really drunk... I don't think I've ever heard such a unique song before...",
  ui_story_5076_50761000_103_dialog_content = "Don't worry, his singing isn't much better when he's sober.",
  ui_story_5076_50761000_104_dialog_content = "\"Bring me home—\"",
  ui_story_5076_50761000_105_dialog_content = "Was that the Northwind Legion song? It's so... full of emotion.",
  ui_story_5076_50761000_106_dialog_content = "Thanks...",
  ui_story_5076_50761000_107_dialog_content = "I wonder if we'll ever have a home?",
  ui_story_5076_50761000_108_dialog_content = "That's the way to do it, Vice Captain. Our troubles can't bother us if we're too drunk to remember them, right?",
  ui_story_5076_50761000_109_dialog_content = "It's great...",
  ui_story_5076_50761000_110_dialog_content = "I don't think I've ever seen Adras this happy.",
  ui_story_5076_50761000_111_dialog_content = "Is this really okay, Captain?",
  ui_story_5076_50761000_112_dialog_content = "It looks like Friegson is almost at her limit, and despite Freya's apparent optimism, I'm sure she's also...",
  ui_story_5076_50761000_113_dialog_content = "This world doesn't need us anymore. If anything, our existence is too much of a threat to peace.",
  ui_story_5076_50761000_114_dialog_content = "I told you before, didn't I? We're nothing but weapons at the kingdom's disposal. Sooner or later, they're going to use us again.",
  ui_story_5076_50761000_115_dialog_content = "Even now, my conscience feels like it's being eaten away.",
  ui_story_5076_50761000_116_dialog_content = "How much longer before one of us makes a mistake?",
  ui_story_5076_50761000_117_dialog_content = "That's enough, Cynthia. There's nothing more valuable to us than rationality, but that doesn't make us heartless.",
  ui_story_5076_50761000_118_dialog_content = "But if we're not dealt with soon, one of these days, we'll—",
  ui_story_5076_50761000_119_dialog_content = "These aren't the kinds of things you should be thinking about! We're not like monsters in a fairy tale!",
  ui_story_5076_50761000_120_dialog_content = "Stop fighting, you two! It's rare for all of us to spend time together like this...",
  ui_story_5076_50761000_121_dialog_content = "I refuse to hurt my friends in any way.",
  ui_story_5076_50761000_122_dialog_content = "It's easy enough to say that when we still have a choice... But what happens when we don't?",
  ui_story_5076_50761000_123_dialog_content = "Are you sure you won't regret it?",
  ui_story_5076_50761000_124_dialog_content = "So long as I continue to be Achilles, I swear on my name that I will never raise my blade against my comrades.",
  ui_story_5076_50761000_125_dialog_content = "I only joined the military to keep the flames of war from reaching the forest...",
  ui_story_5076_50761000_126_dialog_content = "The moment I set foot outside my home, I realized that this world is just an even bigger forest.",
  ui_story_5076_50761000_127_dialog_content = "I wish I could apologize to you with all my soul...",
  ui_story_5076_50761000_128_dialog_content = "But unfortunately, I'm not sure if this body still has a soul or not.",
  ui_story_5076_50761000_129_dialog_content = "Either way, I'm sorry.",
  ui_story_5076_50761101_1_dialog_content = "Regal, there's a new order for you.",
  ui_story_5076_50761101_2_dialog_content = "Frostfire, your fellow Silent Hunter, has gone berserk in another city.",
  ui_story_5076_50761101_3_dialog_content = "What?!",
  ui_story_5076_50761101_4_dialog_content = "Use your water magic to stop her.",
  ui_story_5076_50761101_5_dialog_content = "If necessary... no mercy, take her down.",
  ui_story_5076_50761101_6_dialog_content = "Friegson... Why...",
  ui_story_5076_50761101_7_dialog_content = "This is—",
  ui_story_5076_50761101_8_dialog_content = "The entire city... It's been burned to the ground?",
  ui_story_5076_50761101_9_dialog_content = "Sentries, report the situation! Any survivors in the city?",
  ui_story_5076_50761101_10_dialog_content = "Report! No survivors in the city, and she's still out of control!",
  ui_story_5076_50761101_11_dialog_content = "Quick! Deploy the new \"monster\" and let them battle it out, or else other places might be in danger!",
  ui_story_5076_50761101_12_dialog_content = "Friegson... Friegson...",
  ui_story_5076_50761101_13_dialog_content = "Vice Captain...? Please... Help me...",
  ui_story_5076_50761101_14_dialog_content = "No... You're—An Eclipsite!",
  ui_story_5076_50761101_15_dialog_content = "<size=45>An Eclipsite!!!</size>",
  ui_story_5076_50761101_16_dialog_content = "<size=45>Die!!!</size>",
  ui_story_5076_50761102_1_dialog_content = "Aaaaaaah—Die, Eclipsite!!!",
  ui_story_5076_50761102_2_dialog_content = "Stop, both of you!",
  ui_story_5076_50761102_3_dialog_content = "I can't—I have to burn it all down—",
  ui_story_5076_50761102_4_dialog_content = "Snap out of it, you two! Ludweiss, use your powers to bring them to their senses!",
  ui_story_5076_50761102_5_dialog_content = "Please wake up—",
  ui_story_5076_50761102_6_dialog_content = "C... Captain?",
  ui_story_5076_50761102_7_dialog_content = "Ludweiss?",
  ui_story_5076_50761102_8_dialog_content = "You're finally back to your normal selves... Why were you fighting like this?!",
  ui_story_5076_50761102_9_dialog_content = "Captain, I...",
  ui_story_5076_50761102_10_dialog_content = "Shackles? Why are these on me...?",
  ui_story_5076_50761102_11_dialog_content = "Look around, Friegson. These chains are to protect you.",
  ui_story_5076_50761102_12_dialog_content = "Monsters... Why still keep these dangerous beings around...",
  ui_story_5076_50761102_13_dialog_content = "You swore to protect this place, but you burned it down along with the Eclipsites that were attacking it.",
  ui_story_5076_50761102_14_dialog_content = "How did this happen?",
  ui_story_5076_50761102_15_dialog_content = "Someone... Someone transferred the guards to another post, and let a horde of Eclipsites infiltrate the city and kill countless innocents...",
  ui_story_5076_50761102_16_dialog_content = "I couldn't believe that someone could do something so horrible.",
  ui_story_5076_50761102_17_dialog_content = "So you knew you were being framed from the very beginning?",
  ui_story_5076_50761102_18_dialog_content = "Yes, but... I couldn't control myself any longer.",
  ui_story_5076_50761102_19_dialog_content = "Someone sacrificed all those innocent lives just to smash my heart to pieces...",
  ui_story_5076_50761102_20_dialog_content = "The moment I realized that, darkness clouded my sight. I lost... And before I knew it, I lost all semblance of who I used to be.",
  ui_story_5076_50761102_21_dialog_content = "I'm no hero. Not anymore.",
  ui_story_5076_50761102_22_dialog_content = "Friegson...",
  ui_story_5076_50761102_23_dialog_content = "You have to keep your head up, Friegson. Don't give up.",
  ui_story_5076_50761102_24_dialog_content = "We'll always be at your side.",
  ui_story_5076_50761102_25_dialog_content = "But what should I do now, Captain? Am I...",
  ui_story_5076_50761102_26_dialog_content = "I'll escort you to the royal capital and tell the king the truth of what happened here. We'll request a fair trial for you.",
  ui_story_5076_50761102_27_dialog_content = "What? You can't do that, Captain!",
  ui_story_5076_50761102_28_dialog_content = "You heard it yourself: Friegson was framed, and it's likely that the person responsible is part of the royal court! Sending her there would be no different than sending her to her death!",
  ui_story_5076_50761102_29_dialog_content = "That's right, it must have been Lucius! He's always been against us, and now he's getting rid of us one by one...",
  ui_story_5076_50761102_30_dialog_content = "It doesn't matter anymore, Vice Captain. It's not like I have a home to go back to, anyway...",
  ui_story_5076_50761102_31_dialog_content = "No, this isn't fair to you! Lucius' hands are already at our friend's neck, Captain; how much longer will you let this continue?",
  ui_story_5076_50761102_32_dialog_content = "We have to... stop that man...",
  ui_story_5076_50761102_33_dialog_content = "Calm down, Adras! Freya and Cynthia are still being watched!",
  ui_story_5076_50761102_34_dialog_content = "You also have an entire city and its people to think about... Now's not the time for any reckless decisions.",
  ui_story_5076_50761102_35_dialog_content = "We have to work together and find a way to prove Friegson's innocence, understand?",
  ui_story_5076_50761102_36_dialog_content = "Captain... Why won't you say anything? You used to protect even the lowest of your subordinates, but now you won't even raise a finger to defend one of your closest friends?",
  ui_story_5076_50761102_37_dialog_content = "Captain... Why...",
  ui_story_5076_50761102_38_dialog_content = "Adras, Friegson... I'm sorry.",
  ui_story_5076_50761102_39_dialog_content = "It costs far too much to restore peace to our kingdom. I can't let it fall into chaos once again.",
  ui_story_5076_50761102_40_dialog_content = "If I choose to make a stand, the Elder Council and Lucius will start another war. You don't want to see another bloody rebellion play out, do you?",
  ui_story_5076_50761102_41_dialog_content = "So please... Forgive me.",
  ui_story_5076_50761102_42_dialog_content = "As painful as it is to compromise, all we can do right now is bear it—",
  ui_story_5076_50761200_1_dialog_content = "<color=#e8d9bb>The hero's loss of control quickly sparks fear throughout the kingdom, with complaints flooding into the capital from all corners.</color>",
  ui_story_5076_50761200_2_dialog_content = "<color=#e8d9bb>Frostfire, the one who triggered it all, is now chained up and forced to \"keep fighting\" under the kingdom's watchful eyes.</color>",
  ui_story_5076_50761200_3_dialog_content = "<color=#e8d9bb>The rest of the Silent Hunters are split up and deployed to garrison border towns. Even nearby Caelestites are under house arrest.</color>",
  ui_story_5076_50761200_4_dialog_content = "Go away! Keep that creepy stuff away from our place.",
  ui_story_5076_50761200_5_dialog_content = "I'm just a soldier and this is my weapon. If you refuse to do business with me, at least let my wife go in.",
  ui_story_5076_50761200_6_dialog_content = "Wife...? What a lunatic. Get lost!",
  ui_story_5076_50761200_7_dialog_content = "You would be wise to change your tone and take back your rude comments.",
  ui_story_5076_50761200_8_dialog_content = "Let it go, Adras... You're still their protector, so fighting with them about these things is no use.",
  ui_story_5076_50761200_9_dialog_content = "... Fine.",
  ui_story_5076_50761200_10_dialog_content = "Turns out the rumors are true. Silent Hunters are indeed all a bunch of lunatics...",
  ui_story_5076_50761200_11_dialog_content = "I don't like it here, Marcela.",
  ui_story_5076_50761200_12_dialog_content = "It's okay, Adras. They just don't understand you, that's all.",
  ui_story_5076_50761200_13_dialog_content = "I'm sure they would treat you better if they just had a chance to get to know you—",
  ui_story_5076_50761200_14_dialog_content = "Look, that guy's there again...",
  ui_story_5076_50761200_15_dialog_content = "Eww, he looks like he could lose it at any moment. Who knows when he might...",
  ui_story_5076_50761200_16_dialog_content = "How is everyone today?",
  ui_story_5076_50761200_17_dialog_content = "Get lost! Move!",
  ui_story_5076_50761200_18_dialog_content = "...",
  ui_story_5076_50761200_19_dialog_content = "Don't feel discouraged. Maybe you'll run into someone nicer next time?",
  ui_story_5076_50761200_20_dialog_content = "<color=#e8d9bb>Holding onto a dim hope, the hero yearns for someone else to come to the rescue.</color>",
  ui_story_5076_50761200_21_dialog_content = "Look, here comes the \"Eclipsite.\"",
  ui_story_5076_50761200_22_dialog_content = "An Eclipsite? Where?",
  ui_story_5076_50761200_23_dialog_content = "Get behind me, children! You too, Marcela!",
  ui_story_5076_50761200_24_dialog_content = "I'll handle the Eclipsite—",
  ui_story_5076_50761200_25_dialog_content = "Hah! Idiot!",
  ui_story_5076_50761200_26_dialog_content = "A fool just like the Eclipsite! Hahaha!",
  ui_story_5076_50761200_27_dialog_content = "Those children... Are they starting to think like the adults?",
  ui_story_5076_50761200_28_dialog_content = "What did I do wrong?",
  ui_story_5076_50761200_29_dialog_content = "<color=#e8d9bb>The situation goes on day after day...</color>",
  ui_story_5076_50761200_30_dialog_content = "Why is everyone here afraid of me...?",
  ui_story_5076_50761200_31_dialog_content = "Is it because of these accursed scars...?",
  ui_story_5076_50761200_32_dialog_content = "I'm not an Eclipsite! I know I'm not—",
  ui_story_5076_50761200_33_dialog_content = "See that? That dude would go crazy for no reason.",
  ui_story_5076_50761200_34_dialog_content = "Heard about a Silent Hunter who was just like that, burning down a whole city in the end.",
  ui_story_5076_50761200_35_dialog_content = "Don't know why His Majesty still keeps them; he's too kind.",
  ui_story_5076_50761200_36_dialog_content = "<color=#e8d9bb>He keeps taking attacks from behind, to which he is utterly defenseless.</color>",
  ui_story_5076_50761200_37_dialog_content = "If you ask me, they should all be executed. Who knows what they used to be?",
  ui_story_5076_50761200_38_dialog_content = "Who is \"Marcela\"? When that guy calls out that name, he seems really sad...",
  ui_story_5076_50761200_39_dialog_content = "Perhaps it's someone it once killed, a poor soul. Heard some Eclipsites understand the Universese, and they use lies to deceive others to get close to them.",
  ui_story_5076_50761200_40_dialog_content = "Is that true? Too scary, isn't it?",
  ui_story_5076_50761200_41_dialog_content = "<color=#e8d9bb>The once-bright stars are quickly dimming.</color>",
  ui_story_5076_50761200_42_dialog_content = "Marcela... Is this what happened to Friegson and the others? Is this the kind of life they led?",
  ui_story_5076_50761200_43_dialog_content = "Back then, I didn't know how she felt.",
  ui_story_5076_50761200_44_dialog_content = "If I understood at the time, I could have been there for her. Would things have ended differently for her?",
  ui_story_5076_50761200_45_dialog_content = "<color=#e8d9bb>Then, the hearts of those stars are seized and pulled into the abyss.</color>",
  ui_story_5076_50761200_46_dialog_content = "Oh, Marcela? I finally got a letter from Ludweiss today.",
  ui_story_5076_50761200_47_dialog_content = "It looks like she finally got a chance to break away, and she's coming to visit us soon. Still, I'd like for her to visit her old neighbors first—",
  ui_story_5076_50761200_48_dialog_content = "Hmm? What are you up to?",
  ui_story_5076_50761200_49_dialog_content = "\"Mar—ce—la—\"",
  ui_story_5076_50761200_50_dialog_content = "There's a response! Oh, no, he's looking over here! RUN!",
  ui_story_5076_50761200_51_dialog_content = "What... What exactly am I to them?",
  ui_story_5076_50761200_52_dialog_content = "And why have you stopped whispering in my ear? Marcela...",
  ui_story_5076_50761200_53_dialog_content = "<color=#e8d9bb>When the stars slash across the sky and plummet to the earth, will they finally return to the peace they deserve? Or is it simply a fall from the distant heavens?</color>",
  ui_story_5076_50761200_54_dialog_content = "<color=#e8d9bb>Stars that once shone upon the masses, will they ever find a place to belong?</color>",
  ui_story_5076_50761200_55_dialog_content = "<color=#e8d9bb>If the future is left with only despair when the beautiful dream is shattered... does the fight still hold any meaning at that point?</color>",
  ui_story_5076_50761200_56_dialog_content = "Get away from me, you brat! Stop following me!",
  ui_story_5076_50761200_57_dialog_content = "\"Marcela—Marcela—\"",
  ui_story_5076_50761200_58_dialog_content = "Looks like he's about to cry.",
  ui_story_5076_50761200_59_dialog_content = "Hurry, let's go! The \"Eclipsite\" is gonna lose his temper.",
  ui_story_5076_50761200_60_dialog_content = "Die... Die... Die... Die—",
  ui_story_5076_50761200_61_dialog_content = "<size=45>Eclipsite!!!</size>",
  ui_story_5076_50761200_62_dialog_content = "I don't see it... Where's the Eclipsite?",
  ui_story_5076_50761200_63_dialog_content = "And where are you, Marcela?",
  ui_story_5076_50761200_64_dialog_content = "Please, just call out to me like you used to...",
  ui_story_5076_50761300_1_dialog_content = "<color=#e8d9bb>The kingdom's power was supposed to be delicately balanced, but the King's persistent attitude finally crushed the Elder Council he hated.</color>",
  ui_story_5076_50761300_2_dialog_content = "<color=#e8d9bb>Since the ousting of the Prime Elder, High Priest Lucius has initiated his purge.</color>",
  ui_story_5076_50761300_3_dialog_content = "<color=#e8d9bb>Are the High Priest's actions truly driven by his selfish motives? Or has he always been a mouthpiece for someone else?</color>",
  ui_story_5076_50761300_4_dialog_content = "Open up, Adras.",
  ui_story_5076_50761300_5_dialog_content = "Who are you people? Wait... Captain?",
  ui_story_5076_50761300_6_dialog_content = "What's the matter? Did you forget our faces already?",
  ui_story_5076_50761300_7_dialog_content = "That's harsh, Vice Captain. Especially since we came to take shelter here with you.",
  ui_story_5076_50761300_8_dialog_content = "What happened?",
  ui_story_5076_50761300_9_dialog_content = "A rebel conspiracy was uncovered within the Elder Council. Under secret orders from the king, Lucius wanted to use the Silent Hunters to suppress it.",
  ui_story_5076_50761300_10_dialog_content = "But Friegson and Freya refused to comply, and as a result... They were arrested and imprisoned.",
  ui_story_5076_50761300_11_dialog_content = "I refuse to unleash my flames on the people, even if it means I have to die.",
  ui_story_5076_50761300_12_dialog_content = "That's when Achilles staged a dangerous rescue, and bailed me out of house arrest to boot.",
  ui_story_5076_50761300_13_dialog_content = "But it was all thanks to Cynthia and Ludweiss that we were able to escape from the capital safely.",
  ui_story_5076_50761300_14_dialog_content = "Calls for their immediate capture will be made soon. I want you to escort them out of the kingdom before then.",
  ui_story_5076_50761300_15_dialog_content = "What about you?",
  ui_story_5076_50761300_16_dialog_content = "I bear full responsibility for all of this, which is why I'll return to the capital and accept the king's punishment.",
  ui_story_5076_50761300_17_dialog_content = "He thinks that by turning himself in, he can secure our freedom.",
  ui_story_5076_50761300_18_dialog_content = "What? Are you out of your mind, Achilles?! We have to stay together!",
  ui_story_5076_50761300_19_dialog_content = "The man who sits on the throne was once my brother-in-arms. As two sides of a phalanx, he saved my life countless times.",
  ui_story_5076_50761300_20_dialog_content = "I could never turn my back on him.",
  ui_story_5076_50761300_21_dialog_content = "Rest assured, I'll find a way to speak to the king. There's still hope for a better outcome.",
  ui_story_5076_50761300_22_dialog_content = "There's no changing the Captain's mind once he decides to do something. Just give it up, Vice Commander.",
  ui_story_5076_50761300_23_dialog_content = "At least let us spend some time together before parting ways again.",
  ui_story_5076_50761300_24_dialog_content = "With things the way they are nowadays, does it even matter anymore?",
  ui_story_5076_50761300_25_dialog_content = "Nothing good will come of us gathering like this.",
  ui_story_5076_50761300_26_dialog_content = "Don't say that, Friegson. Achilles fought hard to rescue everyone and bring us here.",
  ui_story_5076_50761300_27_dialog_content = "Sorry.",
  ui_story_5076_50761300_28_dialog_content = "I think it's a great idea! It's been too long since I've had the Vice Captain's wine, and just thinking about it really takes me back.",
  ui_story_5076_50761300_29_dialog_content = "Then just wait here for me. I'll be back in a minute.",
  ui_story_5076_50761300_30_dialog_content = "We shouldn't just sit around and wait for the booze. Let's whip up something to eat in the meantime!",
  ui_story_5076_50761300_31_dialog_content = "This place has seen better days. Has the Vice Captain always been this messy?",
  ui_story_5076_50761300_32_dialog_content = "... Does anyone notice something different about the Vice Captain's mental state?",
  ui_story_5076_50761300_33_dialog_content = "What are you talking about? Aside from the Captain, he's always done better than any of us.",
  ui_story_5076_50761300_34_dialog_content = "That pure and powerful love in his heart has kept his corruption at bay for years now.",
  ui_story_5076_50761300_35_dialog_content = "But Freya, I can smell something on him... The scent of despair.",
  ui_story_5076_50761300_36_dialog_content = "He's one of us, after all.",
  ui_story_5076_50761300_37_dialog_content = "No way! I can't think of a more hopeful—",
  ui_story_5076_50761300_38_dialog_content = "<size=50>Aaaaahhhh!!!!</size>",
  ui_story_5076_50761300_39_dialog_content = "What was that? Let's go, Achilles!",
  ui_story_5076_50761300_40_dialog_content = "Was that... The Vice Captain's voice?",
  ui_story_5076_50761300_41_dialog_content = "What if I told you that the most seriously wounded person in our group is none other than our \"shield\"?",
  ui_story_5076_50761300_42_dialog_content = "Would you still think there's hope, Freya?",
  ui_story_5076_50761300_43_dialog_content = "<size=45>Aahhhh!!!</size>",
  ui_story_5076_50761300_44_dialog_content = "<size=45>Eclipsites! Eclipsites!!!</size>",
  ui_story_5076_50761300_45_dialog_content = "What is this?",
  ui_story_5076_50761300_46_dialog_content = "So much destruction... It's as if not a single inch of this place was spared...",
  ui_story_5076_50761300_47_dialog_content = "Why?! What are Eclipsites doing in the basement of my home?!",
  ui_story_5076_50761300_48_dialog_content = "Why didn't I notice them earlier?!",
  ui_story_5076_50761300_49_dialog_content = "These slash marks were made by a sword, Ludweiss...",
  ui_story_5076_50761300_50_dialog_content = "<size=45>Why? Why?!?</size>",
  ui_story_5076_50761300_51_dialog_content = "Settle down, Adras. We're all here right now, and there aren't any Eclipsites around.",
  ui_story_5076_50761300_52_dialog_content = "No! They lied! They all lied to me!",
  ui_story_5076_50761300_53_dialog_content = "They never got rid of the Eclipsite that was destroying the temple, and now it followed me home!",
  ui_story_5076_50761300_54_dialog_content = "They were all too scared to kill it, but I haven't been able to find it myself...",
  ui_story_5076_50761300_55_dialog_content = "How could there be an Eclipsite as powerful as this? I have no way of defeating it, and Marcela won't come out of hiding because of it...",
  ui_story_5076_50761300_56_dialog_content = "Can you sense its location, Ludweiss? I can't let it hurt anyone else!",
  ui_story_5076_50761300_57_dialog_content = "I won't let anyone else fall at the hands of the Eclipsites. Not again...",
  ui_story_5076_50761300_58_dialog_content = "Captain... I think he's finally...",
  ui_story_5076_50761300_59_dialog_content = "So even a love as pure as his can't stop this horrible corruption from spreading?",
  ui_story_5076_50761300_60_dialog_content = "There really is no future for us after all.",
  ui_story_5076_50761300_61_dialog_content = "Can't you use your Caelestite powers to stabilize his mind, Ludweiss?",
  ui_story_5076_50761300_62_dialog_content = "I'm sorry Achilles, but I would've done that a long time ago if it was possible...",
  ui_story_5076_50761300_63_dialog_content = "Get behind me, everyone! There's no telling when that Eclipsite will attack, so stay alert!",
  ui_story_5076_50761300_64_dialog_content = "It's too powerful to...",
  ui_story_5076_50761300_65_dialog_content = "To...",
  ui_story_5076_50761300_66_dialog_content = "What did you do?",
  ui_story_5076_50761300_67_dialog_content = "I just put him to sleep for a while...",
  ui_story_5076_50761300_68_dialog_content = "You did it so easily, as though he was completely defenseless.",
  ui_story_5076_50761300_69_dialog_content = "He must be so tired. All this time, he was the most lonely out of all of us.",
  ui_story_5076_50761300_70_dialog_content = "Do you think he can still have good dreams?",
  ui_story_5076_50761300_71_dialog_content = "I certainly hope so.",
  ui_story_5076_50761300_72_dialog_content = "You were right, Cynthia: I feel so much regret now. Was I being too arrogant?",
  ui_story_5076_50761300_73_dialog_content = "I thought I could shoulder everything, but I haven't helped a single person.",
  ui_story_5076_50761300_74_dialog_content = "If I had made my decision back then and freed you all from your pain—",
  ui_story_5076_50761300_75_dialog_content = "You were planning to finish us off in that cave during our last mission, weren't you? But in the end, you couldn't bring yourself to do it.",
  ui_story_5076_50761300_76_dialog_content = "This is all my fault.",
  ui_story_5076_50761300_77_dialog_content = "It's not your fault that things ended up this way, or anyone else's fault.",
  ui_story_5076_50761300_78_dialog_content = "To kill with a weapon in times of war isn't a sin, but in times of peace... A weapon's very existence is a sin.",
  ui_story_5076_50761300_79_dialog_content = "Do those ordinary people who reject us actually hate us from the bottom of their hearts? No—I think they just haven't had a chance to understand us.",
  ui_story_5076_50761300_80_dialog_content = "All it takes is the right opportunity... Just like how the Vice Captain and his wife protected these people, and they took care of him in return...",
  ui_story_5076_50761300_81_dialog_content = "Unfortunately, we have no way of making everyone in the world understand us.",
  ui_story_5076_50761300_82_dialog_content = "If there's anyone or anything to blame for all of this, it's destiny.",
  ui_story_5076_50761300_83_dialog_content = "Even so, I have no regrets.",
  ui_story_5076_50761300_84_dialog_content = "Agreed. I willingly accepted this outcome in exchange for saving our land from the Eclipsites. If I have to burn for that cause, then so be it.",
  ui_story_5076_50761300_85_dialog_content = "That doesn't make me a coward, does it?",
  ui_story_5076_50761300_86_dialog_content = "Friegson, everyone... If the day ever comes when I fully turn into an Eclipsite, don't you dare show me any mercy.",
  ui_story_5076_50761300_87_dialog_content = "I think I'll be gone before you... So until then, keep your lightning as accurate as it is today.",
  ui_story_5076_50761300_88_dialog_content = "... Is this really the only outcome for everyone?",
  ui_story_5076_50761300_89_dialog_content = "At the very least, I refuse to accept it.",
  ui_story_5076_50761300_90_dialog_content = "Still writing in your journal, huh?",
  ui_story_5076_50761300_91_dialog_content = "Making a record of this won't change anything.",
  ui_story_5076_50761300_92_dialog_content = "Even undying monsters like ourselves can't see our own futures clearly.",
  ui_story_5076_50761300_93_dialog_content = "I'm barely holding on to my past memories as it is. All of those happy days are slowly being corroded by the darkness...",
  ui_story_5076_50761300_94_dialog_content = "Maybe things would be better if we were all forgotten—",
  ui_story_5076_50761300_95_dialog_content = "Of course it makes a difference!",
  ui_story_5076_50761300_96_dialog_content = "I'm a Caelestite, remember? No one understands feelings and memories more than my people!",
  ui_story_5076_50761300_97_dialog_content = "If someone ever reads this journal... At least they'll know about the stars that guided the people of our time.",
  ui_story_5076_50761300_98_dialog_content = "And if that person happens to be another Caelestite, they'll inherit my memories and my will, and know exactly how I feel about all of you...",
  ui_story_5076_50761300_99_dialog_content = "Even shooting stars have a home in the hearts of those who see their beauty.",
  ui_story_5076_50761300_100_dialog_content = "It definitely means something, so please... Just let me keep writing.",
  ui_story_5076_50761300_101_dialog_content = "Fine, but you're going to soak through all your pages if you don't stop crying.",
  ui_story_5076_50761300_102_dialog_content = "You can be so stubborn sometimes, Ludweiss... So let's do it together.",
  ui_story_5076_50761300_103_dialog_content = "After all... One person couldn't possibly write down all of our memories together, right?",
  ui_story_5076_50761300_104_dialog_content = "Let us help you keep hope alive!",
  ui_story_5076_50761300_105_dialog_content = "At least one of us is bound to make it far into the future. When that happens, no matter who it is—",
  ui_story_5076_50761300_106_dialog_content = "Please don't forget about us.",
  ui_story_5076_50761400_1_dialog_content = "<color=#e8d9bb>As the travelers cross the border, the captain turns around as planned.</color>",
  ui_story_5076_50761400_2_dialog_content = "<color=#e8d9bb>He'd act as a \"sacrifice,\" handing himself over to the pursuers to secure the freedom of the other five.</color>",
  ui_story_5076_50761400_3_dialog_content = "<color=#e8d9bb>But would these Star Warriors really accept such a trade?</color>",
  ui_story_5076_50761400_4_dialog_content = "Their in your hands now, Ludweiss. If any of them wake up, put them back to sleep right away.",
  ui_story_5076_50761400_5_dialog_content = "Do you really intend to rescue Achilles all by yourself, Adras?",
  ui_story_5076_50761400_6_dialog_content = "Aren't you forgetting who I am? I'm Adras, the man who ended a war! I'm more than enough for the likes of them.",
  ui_story_5076_50761400_7_dialog_content = "Head back for now. The Captain and I will catch up to you soon enough.",
  ui_story_5076_50761400_8_dialog_content = "Adras...",
  ui_story_5076_50761400_9_dialog_content = "Is the Vice Captain gone?",
  ui_story_5076_50761400_10_dialog_content = "I can still faintly hear his footsteps. Let him go a little further first.",
  ui_story_5076_50761400_11_dialog_content = "H-Huh?",
  ui_story_5076_50761400_12_dialog_content = "We're the Silent Hunters. There aren't any others like us in the world anymore.",
  ui_story_5076_50761400_13_dialog_content = "We may not have a home, but as long as we stay together, that's more than enough for us.",
  ui_story_5076_50761400_14_dialog_content = "Roaming the land as a group of hated outcasts... That sounds good to me.",
  ui_story_5076_50761400_15_dialog_content = "Even if the entire world denies our future, we still refuse to surrender.",
  ui_story_5076_50761400_16_dialog_content = "Do you still plan on stopping us, Ludweiss?",
  ui_story_5076_50761400_17_dialog_content = "I had a feeling I was being followed, and just as I thought...",
  ui_story_5076_50761400_18_dialog_content = "We meet again, hero. Surely this must be fate?",
  ui_story_5076_50761400_19_dialog_content = "Lucius, you villain! For the future of the kingdom, I swear I'll—",
  ui_story_5076_50761400_20_dialog_content = "You and the other Hunters have already chosen to betray us. What right do you have to talk about the kingdom's future?",
  ui_story_5076_50761400_21_dialog_content = "Guards! Arrest this so-called \"hero\"!",
  ui_story_5076_50761400_22_dialog_content = "Stand aside! Don't think you can stop me!",
  ui_story_5076_50761400_23_dialog_content = "I refuse to raise my blade against innocent people!",
  ui_story_5076_50761400_24_dialog_content = "A touching sentiment, but utterly pointless. Take a look at these soldiers, Adras; they're no different than you!",
  ui_story_5076_50761400_25_dialog_content = "What?",
  ui_story_5076_50761400_26_dialog_content = "Rarrr! Grrrr!",
  ui_story_5076_50761400_27_dialog_content = "They're all Eclipsites?!",
  ui_story_5076_50761400_28_dialog_content = "But they're wearing soldier uniforms! This can't be right!",
  ui_story_5076_50761400_29_dialog_content = "Just like you, they're nothing more than modified monsters now. Granted, they're not nearly as strong as you, but they're far more obedient.",
  ui_story_5076_50761400_30_dialog_content = "What do you mean by \"modified\"? What have you done to the proud soldiers of our kingdom?!",
  ui_story_5076_50761400_31_dialog_content = "Have you forgotten already, Adras? Perhaps the corruption has finally spread into your mind?",
  ui_story_5076_50761400_32_dialog_content = "If so, it would only be all the more laughable.",
  ui_story_5076_50761400_33_dialog_content = "Don't listen to him, Adras! Once I'm free, I'll—",
  ui_story_5076_50761400_34_dialog_content = "Guards, subdue the captain!",
  ui_story_5076_50761400_35_dialog_content = "Achilles! You monster, Lucius! How could you do something so horrible to these loyal soldiers? I—",
  ui_story_5076_50761400_36_dialog_content = "Heheh, they're a bit stronger than you anticipated, no?",
  ui_story_5076_50761400_37_dialog_content = "That's because they're the latest batch of augmented soldiers from the Silent Hunters project.",
  ui_story_5076_50761400_38_dialog_content = "Splendid, aren't they? They're even closer to being Eclipsites than any previous versions!",
  ui_story_5076_50761400_39_dialog_content = "They're safer, easier to control, and completely devoid of reason. After all, it would only get in their way.",
  ui_story_5076_50761400_40_dialog_content = "Stop talking, Lucius, or else I won't be able to hold back any longer.",
  ui_story_5076_50761400_41_dialog_content = "Oh no, you couldn't possibly kill me. I'm the king's most trusted advisor, remember? If you raise so much as a finger towards me, I will destroy everything you've worked so hard to protect.",
  ui_story_5076_50761400_42_dialog_content = "Besides, you've tolerated so much already. Why stop now?",
  ui_story_5076_50761400_43_dialog_content = "As powerful as the Silent Hunters may be, they have all been corrupted by Darkflow. Your rapidly deteriorating psychological states are the reason why I believe you should all be eradicated.",
  ui_story_5076_50761400_44_dialog_content = "Tell me, mighty hero: how many of your precious memories have been swallowed up by the darkness in your heart? Or have you been living in a state of delirium all this time?",
  ui_story_5076_50761400_45_dialog_content = "Die, you monster!",
  ui_story_5076_50761400_46_dialog_content = "Let go of me!",
  ui_story_5076_50761400_47_dialog_content = "Lucius! For toying with people's lives and trampling on our loyalty, you deserve nothing but the worst of deaths!",
  ui_story_5076_50761400_48_dialog_content = "If that's what I deserve, then what about a half-Eclipsite abomination like you?",
  ui_story_5076_50761400_49_dialog_content = "Take a look at the reflection on your blade, Adras. Do you see yourself clearly now?",
  ui_story_5076_50761400_50_dialog_content = "It seems you really have forgotten the truth. The monster you've been howling about...",
  ui_story_5076_50761400_51_dialog_content = "Is none other than you!",
  ui_story_5076_50761400_52_dialog_content = "Don't listen to him, Adras!",
  ui_story_5076_50761400_53_dialog_content = "He's right, Adras! You're not a monster!",
  ui_story_5076_50761400_54_dialog_content = "Marcela? When did you get here?",
  ui_story_5076_50761400_55_dialog_content = "Don't you know how dangerous it is here? Get behind me, hurry!",
  ui_story_5076_50761400_56_dialog_content = "Is this truly the man you've risked life and limb to protect, Achilles? A complete madman?",
  ui_story_5076_50761400_57_dialog_content = "Get back! I won't let you hurt her!",
  ui_story_5076_50761400_58_dialog_content = "Urgh—",
  ui_story_5076_50761400_59_dialog_content = "You've lost too much blood, Adras! Stop trying to defend me!",
  ui_story_5076_50761400_60_dialog_content = "This is nothing, Marcela. Just stay back and leave it all to me...",
  ui_story_5076_50761400_61_dialog_content = "No! I don't want to see you get hurt because of me!",
  ui_story_5076_50761400_62_dialog_content = "Stop it, all of you! He's the greatest hero of our kingdom—",
  ui_story_5076_50761400_63_dialog_content = "Don't hurt my poor Adras anymore!",
  ui_story_5076_50761400_64_dialog_content = "<size=45>Marcela!!!</size>",
  ui_story_5076_50761400_65_dialog_content = "It's okay, Adras... I'll always be with you...",
  ui_story_5076_50761400_66_dialog_content = "Why... This can't be...",
  ui_story_5076_50761400_67_dialog_content = "You've been shouting that name like a lunatic all this time. Marcela...",
  ui_story_5076_50761400_68_dialog_content = "That was your dead wife's name, wasn't it?",
  ui_story_5076_50761400_69_dialog_content = "Dead? No—She wasn't dead! I saved her!",
  ui_story_5076_50761400_70_dialog_content = "I made it to her just in time...",
  ui_story_5076_50761400_71_dialog_content = "You're finally back, Adras.",
  ui_story_5076_50761400_72_dialog_content = "I waited so long... For you.",
  ui_story_5076_50761400_73_dialog_content = "Is that so?",
  ui_story_5076_50761400_74_dialog_content = "I believe you remember the truth now, Adras. Your wife has long since...",
  ui_story_5076_50761400_75_dialog_content = "<size=45>Lucius!</size>",
  ui_story_5076_50761400_76_dialog_content = "No... That can't be... Tell me it's not true, Marcela...",
  ui_story_5076_50761400_77_dialog_content = "All those happy days we spent together afterward... All those times you welcomed me back from the front lines... Tell me it wasn't a lie, Marcela...",
  ui_story_5076_50761400_78_dialog_content = "That day...",
  ui_story_5076_50761400_79_dialog_content = "Urgh... My head... No...",
  ui_story_5076_50761400_80_dialog_content = "Nooo!!!",
  ui_story_5076_50761400_81_dialog_content = "Don't make me see it again!!!",
  ui_story_5076_50761400_82_dialog_content = "By joining the Silent Hunters, you must accept that the modifications will endow you with a portion of Eclipsite power.",
  ui_story_5076_50761400_83_dialog_content = "When the modifications are complete, you will be stronger than ever before, but you must also stave off the corruption of Darkflow at all times.",
  ui_story_5076_50761400_84_dialog_content = "It may interfere with your sanity, or even deprive you of your memories.",
  ui_story_5076_50761400_85_dialog_content = "I... I don't care anymore.",
  ui_story_5076_50761400_86_dialog_content = "To prevent your memories of Marcela from being destroyed, I asked Ludweiss to extract your love for her and seal it within your sword.",
  ui_story_5076_50761400_87_dialog_content = "You shouldn't be troubled by your hallucinations anymore... Look at me, Adras. Do you remember anything else?",
  ui_story_5076_50761400_88_dialog_content = "Marcela... Back then, she...",
  ui_story_5076_50761400_89_dialog_content = "No, no, no—",
  ui_story_5076_50761400_90_dialog_content = "No more!",
  ui_story_5076_50761400_91_dialog_content = "... I failed to keep my promise. I let her down.",
  ui_story_5076_50761400_92_dialog_content = "I abandoned her, and she <size=45>died in darkness and despair</size>.",
  ui_story_5076_50761400_93_dialog_content = "I don't want to think about anything anymore, so modify me as much as possible... Besides, I've already lost it all.",
  ui_story_5076_50761400_94_dialog_content = "I'll do anything if it means I can keep killing Eclipsites.",
  ui_story_5076_50761400_95_dialog_content = "The moment Marcela died, he started having those hallucinations... No one should have to live like this.",
  ui_story_5076_50761400_96_dialog_content = "Are you sure there's no way to get rid of his memories regarding her death, Ludweiss?",
  ui_story_5076_50761400_97_dialog_content = "Memories aren't like rope, Achilles. I can't just cut out a piece and tie the rest together.",
  ui_story_5076_50761400_98_dialog_content = "If I try to remove a memory as painful as that, it will also affect the rest of his memories of Marcela.",
  ui_story_5076_50761400_99_dialog_content = "Or are you asking me to erase her from his mind entirely? Because that would be far crueler than anything else.",
  ui_story_5076_50761400_100_dialog_content = "Just leave him like this. At the very least, the love in his blade is safe from the corruption in his body. He's going to make it, I'm sure of it...",
  ui_story_5076_50761400_101_dialog_content = "Even though you didn't agree with my use of hatred to drive him into battle, I wanted to protect him just like you.",
  ui_story_5076_50761400_102_dialog_content = "Do you really think this is for the best? Leaving him trapped in an illusion, constantly searching for <color=#FFB400>false</color> comfort? If something ever wakes him from this <color=#FFB400>sweet delusion</color>...",
  ui_story_5076_50761400_103_dialog_content = "As long as <color=#FFB400>his sword is by his side</color>, the illusion will continue to preserve his sense of self, as well as his memories of Marcela.",
  ui_story_5076_50761400_104_dialog_content = "Trust me, it's better than letting him face the cruel reality of her death and allowing hatred to warp his heart...",
  ui_story_5076_50761400_105_dialog_content = "M-Marcela? Stay back, it's dangerous here!",
  ui_story_5076_50761400_106_dialog_content = "Is that... the Silent Hunter?",
  ui_story_5076_50761400_107_dialog_content = "So terrifying. Hard to imagine he's a legendary hero. Look at him! He's utterly... <color=#FFB400>CRAZY</color>!",
  ui_story_5076_50761400_108_dialog_content = "If you refuse to do business with me, at least let my wife go in.",
  ui_story_5076_50761400_109_dialog_content = "<color=#FFB400>Wife? When did you get a wife? Get lost, you lunatic!</color>",
  ui_story_5076_50761400_110_dialog_content = "It seems you really have forgotten the truth. The monster you've been howling about...",
  ui_story_5076_50761400_111_dialog_content = "Is none other than you!",
  ui_story_5076_50761400_112_dialog_content = "The temple—",
  ui_story_5076_50761400_113_dialog_content = "Marcela is afraid of the temple—",
  ui_story_5076_50761400_114_dialog_content = "No, that's not it. I'm the one who's afraid of it... Because that pile of rubble is where Marcela <color=#FFB400>died</color>.",
  ui_story_5076_50761400_115_dialog_content = "That's why I have to destroy it—",
  ui_story_5076_50761400_116_dialog_content = "<color=#FFB400>I have to destroy it all!</color>",
  ui_story_5076_50761400_117_dialog_content = "<size=45>Aaaaaah!!!</size>",
  ui_story_5076_50761400_118_dialog_content = "<size=45>Die, Eclipsites!!!</size>",
  ui_story_5076_50761400_119_dialog_content = "<size=50>All of you must die!!!</size>",
  ui_story_5076_50761500_1_dialog_content = "What happened here? The ground... It's covered with Eclipsite remains!",
  ui_story_5076_50761500_2_dialog_content = "It's the Vice Captain. He must have gone berserk again.",
  ui_story_5076_50761500_3_dialog_content = "We have to stop him before he hurts Ludweiss!",
  ui_story_5076_50761500_4_dialog_content = "I see someone trying to escape from over there...",
  ui_story_5076_50761500_5_dialog_content = "Get over here, Cynthia! We... We can't hold the Vice Captain back anymore!",
  ui_story_5076_50761500_6_dialog_content = "Marcela—Marcela—!",
  ui_story_5076_50761500_7_dialog_content = "Why... Why couldn't it have been me...",
  ui_story_5076_50761500_8_dialog_content = "Eclipsites! Die, you monsters!!!",
  ui_story_5076_50761500_9_dialog_content = "What happened to him?",
  ui_story_5076_50761500_10_dialog_content = "He was pushed too far just now, and his memories shattered through the illusion that was protecting him.",
  ui_story_5076_50761500_11_dialog_content = "So what should we do?",
  ui_story_5076_50761500_12_dialog_content = "We still have one last option! Remember, Ludweiss?",
  ui_story_5076_50761500_13_dialog_content = "But if we do that...",
  ui_story_5076_50761500_14_dialog_content = "Are you saying you want to leave him like this?",
  ui_story_5076_50761500_15_dialog_content = "Do you still remember what we talked about that day, Captain?",
  ui_story_5076_50761500_16_dialog_content = "I don't think the Vice Captain would mind if you're the one who does it—",
  ui_story_5076_50761500_17_dialog_content = "No! Just... Let me handle it.",
  ui_story_5076_50761500_18_dialog_content = "We're counting on you, Ludweiss...",
  ui_story_5076_50761500_19_dialog_content = "I'm so sorry, Adras... This time, I'll get rid of your suffering at its source!",
  ui_story_5076_50761500_20_dialog_content = "What are you doing, Ludweiss?!",
  ui_story_5076_50761500_21_dialog_content = "I'm completely removing the memories of Marcela from his mind! That way, he can finally start searching for a new future...",
  ui_story_5076_50761500_22_dialog_content = "No...",
  ui_story_5076_50761500_23_dialog_content = "I don't want a new future, so...",
  ui_story_5076_50761500_24_dialog_content = "Don't you dare touch my memories of her! They're all I have left!!!",
  ui_story_5076_50761500_25_dialog_content = "Look out!",
  ui_story_5076_50761500_26_dialog_content = "Ludweiss!",
  ui_story_5076_50761500_27_dialog_content = "(I was so close... But I couldn't finish it...)",
  ui_story_5076_50761500_28_dialog_content = "What are you reading?",
  ui_story_5076_50761500_29_dialog_content = "Oh, just an old and fragmented journal that Ms. Sheol sold to me for cheap. Even though it's missing a lot of pages, the stuff written here is really interesting!",
  ui_story_5076_50761500_30_dialog_content = "(Is this... A memory? But this feeling... It's so distant... I can't see it clearly...)",
  ui_story_5076_50761500_31_dialog_content = "... For some reason, it feels strangely familiar.",
  ui_story_5076_50761500_32_dialog_content = "I know what you mean! As soon as I picked it up, it felt like I was back in Eraveil.",
  ui_story_5076_50761500_33_dialog_content = "Eraveil?",
  ui_story_5076_50761500_34_dialog_content = "Huh? Did you say something?",
  ui_story_5076_50761500_35_dialog_content = "I didn't hear anyone talking.",
  ui_story_5076_50761500_36_dialog_content = "That's weird... Anyways, this journal is a record of a Caelestite's travels! Even though I can't read their writing, I can see the Caelestite's memories just by holding it in my hands.",
  ui_story_5076_50761500_37_dialog_content = "Can you show me too?",
  ui_story_5076_50761500_38_dialog_content = "Really? This is the first time I've seen you this interested in something.",
  ui_story_5076_50761500_39_dialog_content = "Sure, let's see them together! I should be able to use my psychic abilities on you and the journal at the same time...",
  ui_story_5076_50761500_40_dialog_content = "Just let me know if something doesn't feel right—",
  ui_story_5076_50761500_41_dialog_content = "<color=#FFB400>Regal.</color>",
  ui_story_5076_50761500_42_dialog_content = "Were you dreaming about the distant future, Adras? Or did you dream of me after all those years?",
  ui_story_5076_50761500_43_dialog_content = "Could it be... That back then...",
  ui_story_5076_50761500_44_dialog_content = "Finally awake, huh?",
  ui_story_5076_50761500_45_dialog_content = "Captain...? What happened? Where are we?",
  ui_story_5076_50761500_46_dialog_content = "Can you remember anything?",
  ui_story_5076_50761500_47_dialog_content = "I... I'm Regal, and I...",
  ui_story_5076_50761500_48_dialog_content = "I'm supposed to do something... But I can't remember what it is.",
  ui_story_5076_50761500_49_dialog_content = "Captain, he...",
  ui_story_5076_50761500_50_dialog_content = "The kingdom is safe from Eclipsites, which means I can finally go home and enjoy a peaceful life... But where is home?",
  ui_story_5076_50761500_51_dialog_content = "There's this warmth in my chest... I can't really describe it, but I feel so much lighter now.",
  ui_story_5076_50761500_52_dialog_content = "It feels as though I'm missing someone. I can't seem to remember their face for some reason, but I still feel content.",
  ui_story_5076_50761500_53_dialog_content = "Is this the happiness you were telling me about, Captain?",
  ui_story_5076_50761500_54_dialog_content = "Captain? What's the matter?",
  ui_story_5076_50761500_55_dialog_content = "... Leave.",
  ui_story_5076_50761500_56_dialog_content = "Leave? But where should I go?",
  ui_story_5076_50761500_57_dialog_content = "I... I don't know. But if your heart tells you to go somewhere, just follow it.",
  ui_story_5076_50761500_58_dialog_content = "Leave and never come back, Adras.",
  ui_story_5076_50761500_59_dialog_content = "My heart...?",
  ui_story_5076_50761500_60_dialog_content = "That's right... I want to live a quiet, peaceful life... But where should I go to do that?",
  ui_story_5076_50761500_61_dialog_content = "I'm so sorry, everyone. This is all my fault... I couldn't bring myself to do it.",
  ui_story_5076_50761500_62_dialog_content = "I wanted your dreams to end at the perfect moment, but I couldn't do it... I couldn't point my sword at you.",
  ui_story_5076_50761500_63_dialog_content = "So please, just stay away. Don't show your faces in the kingdom ever again.",
  ui_story_5076_50761500_64_dialog_content = "Are you sure you can't come with us, Captain?",
  ui_story_5076_50761500_65_dialog_content = "The kingdom is descending into chaos again. I can't just leave it like this.",
  ui_story_5076_50761500_66_dialog_content = "That cowardly high priest managed to escape... It seems everything is closely tied to the king. Is there really nothing we can do?",
  ui_story_5076_50761500_67_dialog_content = "I... I swore an oath to never attack civilians, so count me out.",
  ui_story_5076_50761500_68_dialog_content = "Forget about it, Cynthia. Confronting the king won't change anything, even if we manage to get revenge on him. It would only create more turmoil for the kingdom.",
  ui_story_5076_50761500_69_dialog_content = "The truth is, the king is just trying to hold onto his power. Aside from that, he's definitely worthy of leading his subjects.",
  ui_story_5076_50761500_70_dialog_content = "But don't his subjects deserve justice too? If nothing gets done, how will they possibly prevent more people from getting hurt?",
  ui_story_5076_50761500_71_dialog_content = "The kingdom is in shambles, and we're seen as nothing but monsters. There's no reason for us to stoke the flames.",
  ui_story_5076_50761500_72_dialog_content = "I see... From staying together to parting ways, all it takes is a single step.",
  ui_story_5076_50761500_73_dialog_content = "Cynthia?",
  ui_story_5076_50761500_74_dialog_content = "It looks like our paths are different after all. In that case, I'm leaving now.",
  ui_story_5076_50761500_75_dialog_content = "I'll respect everyone's decision and refrain from doing anything at all.",
  ui_story_5076_50761500_76_dialog_content = "... I hope you find peace someday, Cynthia. Goodbye.",
  ui_story_5076_50761500_77_dialog_content = "What are your thoughts, Friegson?",
  ui_story_5076_50761500_78_dialog_content = "No matter where I go, I'll always be seen as a criminal. That's why... I want to go with you and turn myself in, Captain.",
  ui_story_5076_50761500_79_dialog_content = "Freya and Adras, take good care of yourselves.",
  ui_story_5076_50761500_80_dialog_content = "How much longer are you going to work for that man?",
  ui_story_5076_50761500_81_dialog_content = "I won't be working for him, Freya. After all of this, I have no hope for anything like that.",
  ui_story_5076_50761500_82_dialog_content = "But the kingdom needs its Claymore if it wants to extinguish the impending rebellion.",
  ui_story_5076_50761500_83_dialog_content = "Just like you, I have a duty that I can't simply abandon.",
  ui_story_5076_50761500_84_dialog_content = "My only advice for you is to take Ludweiss and go somewhere far away from here.",
  ui_story_5076_50761500_85_dialog_content = "Our paths can never cross again.",
  ui_story_5076_50761500_86_dialog_content = "I have a duty to eliminate any and all threats to our kingdom. The next time we meet, I'll have no choice but to...",
  ui_story_5076_50761601_1_dialog_content = "Adras!",
  ui_story_5076_50761601_2_dialog_content = "Are you finally awake? You've been asleep for so long.",
  ui_story_5076_50761601_3_dialog_content = "Why did the Vice Captain suddenly attack you like that? Thankfully, the wound wasn't too serious. I already took care of it for you.",
  ui_story_5076_50761601_4_dialog_content = "But judging from your old wounds, it looks like there's still a risk of corruption... How have you managed to keep it at bay all this time? Is this another one of your Caelestite powers?",
  ui_story_5076_50761601_X4_dialog_content = "... Where's the rest?",
  ui_story_5076_50761601_5_dialog_content = "They're all gone now, even our amnesiac of a Vice Captain. He didn't know where he was going, either.",
  ui_story_5076_50761601_6_dialog_content = "But to be fair, neither do I. Good thing you're still here... At least we can keep wandering around together.",
  ui_story_5076_50761601_7_dialog_content = "I wasn't able to completely erase his memories of Marcela... If he remembers her again...",
  ui_story_5076_50761601_8_dialog_content = "But it looks like the Vice Captain has already lost most of his memories... I wonder where he'll wander off to now?",
  ui_story_5076_50761601_9_dialog_content = "That's right... With your long lifespan, wandering makes a lot of sense...",
  ui_story_5076_50761601_10_dialog_content = "Ludweiss?",
  ui_story_5076_50761601_11_dialog_content = "Do you trust me, Freya?",
  ui_story_5076_50761601_12_dialog_content = "If you do, then help me look for everyone again.",
  ui_story_5076_50761601_13_dialog_content = "That way, there might be a chance to change things for us.",
  ui_story_5076_50761601_14_dialog_content = "These ruins... What is this place? Why did I come here without realizing it?",
  ui_story_5076_50761601_15_dialog_content = "It feels so familiar... Have I been here before?",
  ui_story_5076_50761601_16_dialog_content = "Maybe.",
  ui_story_5076_50761601_17_dialog_content = "Huh? Freya... Is that you?",
  ui_story_5076_50761601_18_dialog_content = "Don't mind me, just keep looking. I'm sure there's something familiar to you hidden in here.",
  ui_story_5076_50761601_19_dialog_content = "These traces of fire and destruction... Were Eclipsites responsible for this?",
  ui_story_5076_50761601_20_dialog_content = "There's a tomb in here too... But who would put this inside a house?",
  ui_story_5076_50761601_21_dialog_content = "This place is covered in weeds, huh?",
  ui_story_5076_50761601_22_dialog_content = "What's this—",
  ui_story_5076_50761601_23_dialog_content = "A burnt mural...?",
  ui_story_5076_50761601_24_dialog_content = "Do you still remember it?",
  ui_story_5076_50761601_25_dialog_content = "What? I don't remember anything... But this mural seems to depict a ceremony of some sort.",
  ui_story_5076_50761601_26_dialog_content = "What could it be...?",
  ui_story_5076_50761601_27_dialog_content = "\"The first person to paint a mural like this was allegedly a madman.\"",
  ui_story_5076_50761601_28_dialog_content = "\"In order to escape the suffering in his life, he created an entirely new reality.\"",
  ui_story_5076_50761601_29_dialog_content = "\"Did it put an end to his suffering?\"",
  ui_story_5076_50761601_30_dialog_content = "\"No. He only sealed it away.\"",
  ui_story_5076_50761601_31_dialog_content = "\"I see...\"",
  ui_story_5076_50761601_32_dialog_content = "M... Marcela?",
  ui_story_5076_50761601_33_dialog_content = "As we work towards our dream, let's keep making beautiful memories together.",
  ui_story_5076_50761601_34_dialog_content = "I promise to cherish every single wonderful moment of our lives—",
  ui_story_5076_50761601_35_dialog_content = "Ah... Ahhh...",
  ui_story_5076_50761601_36_dialog_content = "Marcela... My sweet Marcela...",
  ui_story_5076_50761601_37_dialog_content = "I'm finally... At your side once more...",
  ui_story_5076_50761601_38_dialog_content = "And so ends the story of the great hero Adras. Tell me, Freya; why do we insist on living?",
  ui_story_5076_50761601_39_dialog_content = "What's the point of surviving in this twisted world if it means losing everything we care about?",
  ui_story_5076_50761601_40_dialog_content = "This world doesn't need us anymore.",
  ui_story_5076_50761601_41_dialog_content = "Maybe it's finally time to free Adras from his misery... And ourselves.",
  ui_story_5076_50761601_42_dialog_content = "Ludweiss said she found a path towards a new future for us, albeit at a cost.",
  ui_story_5076_50761601_43_dialog_content = "You're still willing to trust other people?",
  ui_story_5076_50761601_44_dialog_content = "That's right. I'll always place my faith in hope.",
  ui_story_5076_50761601_45_dialog_content = "Let's go, Cynthia. It's time for the Silent Hunters to have one final reunion.",
  ui_story_5076_50761601_X45_dialog_content = "<color=#e8d9bb>So, the stars set out once again, refusing to bow down. After all those battles fought for the retreating God of Light, this time, their fight is finally for themselves.</color>",
  ui_story_5076_50761601_46_dialog_content = "They're here, Achilles.",
  ui_story_5076_50761601_47_dialog_content = "Adras, Freya, Friegson, and even Cynthia... They're all here now.",
  ui_story_5076_50761601_48_dialog_content = "And you're certain this will work, Ludweiss?",
  ui_story_5076_50761601_49_dialog_content = "Not entirely, but... My heart tells me to trust in what I saw when I was unconscious.",
  ui_story_5076_50761601_50_dialog_content = "In a thousand years, they'll still be waiting for a place to call home. When that time comes... They'll finally be free.",
  ui_story_5076_50761601_51_dialog_content = "I'm certain they'll find their happiness then.",
  ui_story_5076_50761601_52_dialog_content = "I trust you, Ludweiss. But what kind of price will you have to pay to seal them away like this?",
  ui_story_5076_50761601_53_dialog_content = "I told you not to underestimate us Caelestites, didn't I? No one understands the power of the soul better than we do!",
  ui_story_5076_50761601_54_dialog_content = "The Silent Hunters were granted immortal bodies as a result of their modifications.",
  ui_story_5076_50761601_55_dialog_content = "And by capturing their powerful emotions and turning them into \"cornerstones,\" their souls can be sealed in a dormant state.",
  ui_story_5076_50761601_56_dialog_content = "They'll remain vigilant within their thousand-year dream, but beyond that... They'll have to use their memories to resist the passage of time.",
  ui_story_5076_50761601_57_dialog_content = "But...",
  ui_story_5076_50761601_58_dialog_content = "Now!",
  ui_story_5076_50761601_59_dialog_content = "What's this... A magic formation? Wait, what do you think you're doing, Captain?!",
  ui_story_5076_50761601_60_dialog_content = "Didn't you call us to the arena to...",
  ui_story_5076_50761601_61_dialog_content = "I'm sorry, but this is the only way I can ensure your eternal peace... I wish you all the sweetest of dreams.",
  ui_story_5076_50761601_62_dialog_content = "<color=#e8d9bb>The passion within Friegson had long been consumed by fire, leaving behind a mere handful of ashes.</color>",
  ui_story_5076_50761601_63_dialog_content = "<color=#e8d9bb>So, the only emotion left to seal her might just be hatred.</color>",
  ui_story_5076_50761601_64_dialog_content = "<color=#e8d9bb>Ordinary Caelestites can't accomplish such a feat, let alone those haunted by old wounds.</color>",
  ui_story_5076_50761601_65_dialog_content = "<color=#e8d9bb>However, if a Caelestite is willing to sacrifice their life, burning themselves to preserve the emotions of others...</color>",
  ui_story_5076_50761601_66_dialog_content = "Sleep!",
  ui_story_5076_50761601_67_dialog_content = "Wh... Why...?",
  ui_story_5076_50761601_68_dialog_content = "You can rest easy now, Friegson. I promise your dreams will be free of sorrow from now on.",
  ui_story_5076_50761601_69_dialog_content = "It doesn't matter... As long as you're the ones betraying me... I don't mind...",
  ui_story_5076_50761601_70_dialog_content = "What have you done to Friegson, Captain? Why would you ambush her like this?!",
  ui_story_5076_50761601_71_dialog_content = "Still in the dark, are we? The king wishes to be rid of you dangerous creatures, and Achilles has chosen to side with his king.",
  ui_story_5076_50761601_72_dialog_content = "Lucius? How are you still alive...?",
  ui_story_5076_50761601_73_dialog_content = "Aren't you going to deny his words, Captain? Just tell me he's lying, and I'll believe you!",
  ui_story_5076_50761601_74_dialog_content = "Guards! Apprehend these vile fugitives!",
  ui_story_5076_50761601_75_dialog_content = "I leave the rest to you, Captain. I trust that you won't disappoint His Majesty, will you?",
  ui_story_5076_50761601_76_dialog_content = "Captain!!!",
  ui_story_5076_50761601_77_dialog_content = "These Eclipsites seem even stronger than before! Cynthia, stay on your...",
  ui_story_5076_50761601_78_dialog_content = "Look out!",
  ui_story_5076_50761601_79_dialog_content = "Cynthia? You...",
  ui_story_5076_50761601_80_dialog_content = "Like I said, Freya... I'll be gone before you. If there's a future for us out there, I hope you'll—",
  ui_story_5076_50761601_81_dialog_content = "Cynthia!",
  ui_story_5076_50761601_82_dialog_content = "As I said before, I have a duty to destroy any and all threats to the kingdom.",
  ui_story_5076_50761601_83_dialog_content = "I'm not your captain anymore. I'm an executioner in service to the kingdom.",
  ui_story_5076_50761601_84_dialog_content = "Come, Regal.",
  ui_story_5076_50761601_85_dialog_content = "Now that you finally remember, concentrate all of your rage and hatred... And unleash it on me.",
  ui_story_5076_50761601_86_dialog_content = "<size=45>You—</size>",
  ui_story_5076_50761601_87_dialog_content = "<size=45>Claymore—!!!</size>",
  ui_story_5076_50761602_1_dialog_content = "<color=#e8d9bb>Despite Adras' evident vulnerability in his emotions, his strength and combat will are incredibly formidable.</color>",
  ui_story_5076_50761602_2_dialog_content = "<color=#e8d9bb>To seize the sword that holds Adras' last memory, Achilles intentionally takes a blow from the sword.</color>",
  ui_story_5076_50761602_3_dialog_content = "Forgive me... Adras.",
  ui_story_5076_50761602_4_dialog_content = "<color=#e8d9bb>After thrusting the sword he had just seized back into Adras, he instantly lost strength, collapsing to the ground.</color>",
  ui_story_5076_50761602_5_dialog_content = "<color=#e8d9bb>Meanwhile, the seal targeting Freya and Cynthia has also been completed.</color>",
  ui_story_5076_50761602_6_dialog_content = "You've done well, loyal captain of the king. Now eradicate these monsters once and for all!",
  ui_story_5076_50761602_7_dialog_content = "Captain Achilles... Why...?",
  ui_story_5076_50761602_8_dialog_content = "Ludweiss says that this is the only way to change our fate, Adras... But don't worry, we'll see each other again someday.",
  ui_story_5076_50761602_9_dialog_content = "When that day comes, I hope you'll find your happiness once again.",
  ui_story_5076_50761602_10_dialog_content = "Is it over now, Ludweiss?",
  ui_story_5076_50761602_11_dialog_content = "Their souls have been sealed away within their undying bodies... Where they'll lie dormant... until...",
  ui_story_5076_50761602_12_dialog_content = "You said that this deep sleep, coupled with their corruption, has a chance of damaging their memories, and even their very sanity...",
  ui_story_5076_50761602_13_dialog_content = "But even if it's just Adras... He has so little joy in his life as it is. At the very least... He should be allowed to hold onto his happy memories, right?",
  ui_story_5076_50761602_14_dialog_content = "I'm sorry... But the Caelestite isn't all-powerful... All we can do now... is hope.",
  ui_story_5076_50761602_15_dialog_content = "Hope that their madness will burn out after a thousand years... If they can remember even a single happy memory by then... It will all be worth it.",
  ui_story_5076_50761602_16_dialog_content = "Urgh, I'm nearly at my limit... But I still haven't gotten to Adras...",
  ui_story_5076_50761602_17_dialog_content = "(Gaze up at the sky, and the stars will shine in response.)",
  ui_story_5076_50761602_18_dialog_content = "(The warmth of their light is still the same, even after a thousand years.)",
  ui_story_5076_50761602_19_dialog_content = "(Let me help you this time!)",
  ui_story_5076_50761602_20_dialog_content = "This voice... Are you from that distant time?",
  ui_story_5076_50761602_X20_dialog_content = "Wake up, Regal!",
  ui_story_5076_50761602_X21_dialog_content = "Then let's see them together... <color=#FFB400>Regal</color>.",
  ui_story_5076_50761602_21_dialog_content = "I see... It looks like my efforts weren't in vain after all...",
  ui_story_5076_50761602_22_dialog_content = "Those starlit memories withstood the test of time, and now they're finally in the hands of another Caelestite...",
  ui_story_5076_50761602_23_dialog_content = "I've been feeling longing all this time, and those voices have been trying so hard to reach me.",
  ui_story_5076_50761602_24_dialog_content = "Our common emotions bind us, creating ties that transcend the flow of time...",
  ui_story_5076_50761602_25_dialog_content = "Adras! I can see it now... That future is real.",
  ui_story_5076_50761602_26_dialog_content = "Countless years from now, someone will be waiting for your triumphant return.",
  ui_story_5076_50761602_27_dialog_content = "I don't want...",
  ui_story_5076_50761602_28_dialog_content = "I don't want everlasting life. I don't need eternity...",
  ui_story_5076_50761602_29_dialog_content = "All I want... is the moment that slipped through my fingers... That's right... All I need is Marcela.",
  ui_story_5076_50761602_30_dialog_content = "So please... Just let me go! I don't want to be sealed away! Let me lay at Marcela's side and sleep for the rest of time!",
  ui_story_5076_50761602_31_dialog_content = "If that's what you want...",
  ui_story_5076_50761602_32_dialog_content = "Help me, Marcela... And you as well, my distant friend—",
  ui_story_5076_50761602_33_dialog_content = "Help me turn his longing into the strength he needs to survive!",
  ui_story_5076_50761602_34_dialog_content = "(Let the person in his memories stay by his side—)",
  ui_story_5076_50761602_35_dialog_content = "... Marcela?",
  ui_story_5076_50761602_36_dialog_content = "Don't cry, Adras... I'm right here...",
  ui_story_5076_50761602_37_dialog_content = "Wait, Marcela! Don't go!",
  ui_story_5076_50761602_38_dialog_content = "I'm not going anywhere, my sweet Adras. I'll always be with you, now and forever...",
  ui_story_5076_50761602_39_dialog_content = "So don't be afraid... Your friends all want you to sleep, now rest your weary head...",
  ui_story_5076_50761602_40_dialog_content = "Sleep... So we can finally—",
  ui_story_5076_50761602_41_dialog_content = "No! Please!",
  ui_story_5076_50761602_42_dialog_content = "Marcela! Don't go!",
  ui_story_5076_50761602_43_dialog_content = "Don't cry, Adras.",
  ui_story_5076_50761602_44_dialog_content = "Our memories, our will... Even our faith.",
  ui_story_5076_50761602_45_dialog_content = "We're leaving them all with Marcela, so she can always be at your side.",
  ui_story_5076_50761602_46_dialog_content = "As long as you still have a bit of attachment to this world and are willing to put your faith in hope.",
  ui_story_5076_50761602_47_dialog_content = "(Your dreams will never be lonely.)",
  ui_story_5076_50761602_48_dialog_content = "You'll always be together.",
  ui_story_5076_50761602_49_dialog_content = "(Come with me, <color=#FFB400>Adras</color>. It's time to wake up from your thousand-year <color=#FFB400>dream</color>—)",
  ui_story_5076_50761602_50_dialog_content = "When you finally <color=#FFB400>awaken</color>, you might not remember anything. If that happens, please don't be sad.",
  ui_story_5076_50761602_51_dialog_content = "Those precious memories will always be sleeping in your heart, Adras.",
  ui_story_5076_50761602_52_dialog_content = "The feelings attached to them will always be a part of your soul.",
  ui_story_5076_50761602_53_dialog_content = "You'll never be alone again.",
  ui_story_5076_50761602_54_dialog_content = "Now please, put your mind at ease and just sleep...",
  ui_story_5076_50761602_55_dialog_content = "There will be a <color=#FFB400>home</color> for you someday, as long as you keep hope alive in your heart. When you find it, peace will come back to you—",
  ui_story_5076_50761602_56_dialog_content = "Marcela... Everyone...",
  ui_story_5076_50761602_57_dialog_content = "*Coughs* I'm sorry, Achilles.",
  ui_story_5076_50761602_58_dialog_content = "But it looks like... My journey's finally at its end.",
  ui_story_5076_50761602_59_dialog_content = "Ludweiss... So this is the price that must be paid? I see... Even a Caelestite can't withstand this much tragedy...",
  ui_story_5076_50761602_60_dialog_content = "Which is why... I'm leaving the future in your hands.",
  ui_story_5076_50761602_61_dialog_content = "Do we really deserve this?",
  ui_story_5076_50761602_62_dialog_content = "Is that even a question? Heheh... I'm so grateful to have known all of you. Thanks to you, this wandering Caelestite finally found the courage to look up at the stars.",
  ui_story_5076_50761602_63_dialog_content = "Thank you all... For shining your light on <color=#FFB400>this world</color>.",
  ui_story_5076_50761602_64_dialog_content = "I understand... Rest easy, Ludweiss.",
  ui_story_5076_50761602_65_dialog_content = "Your memories, your will, your lives...",
  ui_story_5076_50761602_66_dialog_content = "I'll carry them all on my shoulders.",
  ui_story_5076_50761602_67_dialog_content = "There may not be a place for me in the future, but that won't stop me from clearing a path for my friends!",
  ui_story_5076_50761602_68_dialog_content = "What do you think you're doing, Achilles? Why haven't you killed them off yet? You're not planning something, are you?!",
  ui_story_5076_50761602_69_dialog_content = "Stop! Don't come near me!",
  ui_story_5076_50761602_70_dialog_content = "There's something I must do... Something I should've done a long time ago.",
  ui_story_5076_50761602_71_dialog_content = "Achilles? What is the meaning of this?!",
  ui_story_5076_50761602_72_dialog_content = "Now that I'm the only one left... I have to find a way... To see you all again...",
  ui_story_5076_50761602_73_dialog_content = "My final mission... Is to take my <color=#FFB400>longing</color>... And turn it into the cornerstone of a seal.",
  ui_story_5076_50761602_74_dialog_content = "...",
  ui_story_5076_50761602_75_dialog_content = "Don't cry, Adras... There's someone waiting for you in your future.",
  ui_story_5076_50761602_76_dialog_content = "Good things will always happen as long as you keep hope in your heart...",
  ui_story_5076_50761602_77_dialog_content = "So please don't cry anymore.",
  ui_story_5076_50761602_78_dialog_content = "<color=#e8d9bb>All this time, everyone's grown used to the towering presence of the great hero Adras.</color>",
  ui_story_5076_50761602_79_dialog_content = "<color=#e8d9bb>It's so reassuring, yet so... lonely. If he must be put into a thousand-year sleep, at the very least, he should be given company.</color>",
  ui_story_5076_50761602_80_dialog_content = "<color=#e8d9bb>This is the first time \"I\" have touched a sword. A hefty weapon, not something a Caelestite would ever want to handle.</color>",
  ui_story_5076_50761602_81_dialog_content = "<color=#e8d9bb>But this is different.</color>",
  ui_story_5076_50761602_82_dialog_content = "<color=#e8d9bb>This one is not a weapon; it's a warm heart, harboring the sincere love of my dearest friend.</color>",
  ui_story_5076_50761602_83_dialog_content = "<color=#e8d9bb>When I draw it out and place it in Adras's embrace, a smile adorns his face, like a child who just found his long-lost possession.</color>",
  ui_story_5076_50761602_84_dialog_content = "<color=#e8d9bb>It must be incredibly hard to endure such extended periods of loneliness.</color>",
  ui_story_5076_50761602_85_dialog_content = "<color=#e8d9bb>All I can do is offer my best wishes, hoping that he can find comfort with the one in his heart as he closes his eyes.</color>",
  ui_story_5076_50761602_86_dialog_content = "<color=#e8d9bb>If the stars that streak across the sky could one day find where they belong in the gentleness of time...</color>",
  ui_story_5076_50761602_87_dialog_content = "<color=#e8d9bb>May you receive belated happiness.</color>",
  ui_story_5076_50761602_88_dialog_content = "Sweet dreams, Adras."
}
return config
